package com.sun.glass.ui.gtk4.wrappers;

import java.lang.foreign.AddressLayout;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemoryLayout;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;

import static com.sun.glass.ui.gtk4.wrappers.NativeSymbolLookup.invokeLong;
import static com.sun.glass.ui.gtk4.wrappers.NativeSymbolLookup.invokePointer;
import static com.sun.glass.ui.gtk4.wrappers.NativeSymbolLookup.invokeVoid;

/**
 * Static bindings for core GObject operations: reference counting,
 * signal connections and arbitrary data slots.
 * <p>
 * All native symbols are resolved lazily via the inner {@link H} class
 * (Initialization-on-demand Holder idiom).
 */
public final class GObject {
    private GObject() {
    }

    /**
     * Decrements the reference count of a GObject instance.
     */
    public static void unref(MemorySegment object) {
        invokeVoid(H.UNREF, object);
    }

    /**
     * Connects a signal handler to an object (no extra user-data).
     */
    public static long signalConnect(MemorySegment instance, String signal, MemorySegment callback) {
        try (Arena arena = Arena.ofConfined()) {
            return invokeLong(H.SIGNAL_CONNECT,
                    instance, arena.allocateFrom(signal), callback,
                    MemorySegment.NULL, MemorySegment.NULL, 0);
        }
    }

    /**
     * Connects a signal handler to an object with arbitrary user-data.
     */
    public static long signalConnect(MemorySegment instance, String signal,
                                     MemorySegment callback, MemorySegment data) {
        try (Arena arena = Arena.ofConfined()) {
            return invokeLong(H.SIGNAL_CONNECT,
                    instance, arena.allocateFrom(signal), callback,
                    data, MemorySegment.NULL, 0);
        }
    }

    /**
     * Convenience method that creates a native upcall stub for the given
     * instance method and connects it to a GObject signal in one step.
     * <p>
     * The {@link MethodType} for the Java callback is derived automatically
     * from the supplied {@link FunctionDescriptor}, so callers only need to
     * specify the native signature once.
     *
     * @param instance   the GObject (or GtkWidget) to connect to
     * @param signal     the signal name (e.g. {@code "close-request"})
     * @param lookup     a {@link MethodHandles.Lookup} with access to the target method
     * @param target     the object that owns the callback method
     * @param methodName the name of the callback method on {@code target}
     * @param descriptor the native {@link FunctionDescriptor} of the signal callback
     * @param arena      the {@link Arena} that controls the upcall stub lifetime
     */
    public static void connect(MemorySegment instance, String signal,
                               MethodHandles.Lookup lookup, Object target,
                               String methodName, FunctionDescriptor descriptor,
                               Arena arena) {
        try {
            MethodType mt = toMethodType(descriptor);
            MemorySegment cb = Linker.nativeLinker().upcallStub(
                    lookup.bind(target, methodName, mt),
                    descriptor, arena);
            signalConnect(instance, signal, cb);
        } catch (NoSuchMethodException | IllegalAccessException e) {
            throw new RuntimeException(
                    "Failed to connect signal '" + signal + "' to " + methodName, e);
        }
    }

    /**
     * Derives a {@link MethodType} from a {@link FunctionDescriptor} by mapping
     * each native layout to its Java carrier type.
     */
    private static MethodType toMethodType(FunctionDescriptor descriptor) {
        Class<?>[] paramTypes = descriptor.argumentLayouts().stream()
                .map(GObject::carrierFor)
                .toArray(Class<?>[]::new);
        Class<?> returnType = descriptor.returnLayout()
                .<Class<?>>map(GObject::carrierFor)
                .orElse(void.class);
        return MethodType.methodType(returnType, paramTypes);
    }

    private static Class<?> carrierFor(MemoryLayout layout) {
        if (layout instanceof ValueLayout.OfInt) return int.class;
        if (layout instanceof ValueLayout.OfLong) return long.class;
        if (layout instanceof ValueLayout.OfDouble) return double.class;
        if (layout instanceof ValueLayout.OfFloat) return float.class;
        if (layout instanceof AddressLayout) return MemorySegment.class;
        throw new IllegalArgumentException("Unsupported layout: " + layout);
    }

    /**
     * Associates arbitrary data with a GObject under a string key.
     */
    public static void setData(MemorySegment object, String key, MemorySegment data) {
        try (Arena arena = Arena.ofConfined()) {
            invokeVoid(H.SET_DATA, object, arena.allocateFrom(key), data);
        }
    }

    /**
     * Retrieves data previously stored with {@link #setData}.
     */
    public static MemorySegment getData(MemorySegment object, String key) {
        try (Arena arena = Arena.ofConfined()) {
            return invokePointer(H.GET_DATA, object, arena.allocateFrom(key));
        }
    }

    private static final class H {
        static final MethodHandle UNREF = NativeSymbolLookup.load("g_object_unref",
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS));
        static final MethodHandle SIGNAL_CONNECT = NativeSymbolLookup.load("g_signal_connect_data",
                FunctionDescriptor.of(ValueLayout.JAVA_LONG,
                        ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS,
                        ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.JAVA_INT));
        static final MethodHandle SET_DATA = NativeSymbolLookup.load("g_object_set_data",
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS));
        static final MethodHandle GET_DATA = NativeSymbolLookup.load("g_object_get_data",
                FunctionDescriptor.of(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS));
    }
}

