        } catch (NoSuchMethodException | IllegalAccessException e) {
            throw new RuntimeException(
                    "Failed to connect signal '" + signal + "' to " + methodName, e);
        }
    }

    /**
     * Overload that accepts a {@link GtkWidget} directly, since every
     * {@code GtkWidget} is a {@code GObject} in GTK.
     */
    public static void connect(GtkWidget widget, String signal,
                               MethodHandles.Lookup lookup, Object target,
                               String methodName, FunctionDescriptor descriptor,
                               Arena arena) {
        connect(widget.getPointer(), signal, lookup, target, methodName, descriptor, arena);
    }

    /**
     * Derives a {@link MethodType} from a {@link FunctionDescriptor} by mapping
     * each native layout to its Java carrier type.
     */
    private static MethodType toMethodType(FunctionDescriptor descriptor) {
        Class<?>[] paramTypes = descriptor.argumentLayouts().stream()
                .map(GObject::carrierFor)
                .toArray(Class<?>[]::new);
        Class<?> returnType = descriptor.returnLayout()
                .<Class<?>>map(GObject::carrierFor)
                .orElse(void.class);
        return MethodType.methodType(returnType, paramTypes);
    }

    private static Class<?> carrierFor(MemoryLayout layout) {
        if (layout instanceof ValueLayout.OfInt) return int.class;
        if (layout instanceof ValueLayout.OfLong) return long.class;
        if (layout instanceof ValueLayout.OfDouble) return double.class;
        if (layout instanceof ValueLayout.OfFloat) return float.class;
        if (layout instanceof AddressLayout) return MemorySegment.class;
        throw new IllegalArgumentException("Unsupported layout: " + layout);
    }

    /**
     * Associates arbitrary data with a GObject under a string key.
     */
    public static void setData(MemorySegment object, String key, MemorySegment data) {
        try (Arena arena = Arena.ofConfined()) {
            invokeVoid(H.SET_DATA, object, arena.allocateFrom(key), data);
        }
    }

    /**
     * Retrieves data previously stored with {@link #setData}.
     */
    public static MemorySegment getData(MemorySegment object, String key) {
        try (Arena arena = Arena.ofConfined()) {
            return invokePointer(H.GET_DATA, object, arena.allocateFrom(key));
        }
    }

    private static final class H {
        static final MethodHandle UNREF = NativeSymbolLookup.load("g_object_unref",
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS));
        static final MethodHandle SIGNAL_CONNECT = NativeSymbolLookup.load("g_signal_connect_data",
                FunctionDescriptor.of(ValueLayout.JAVA_LONG,
                        ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS,
                        ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.JAVA_INT));
        static final MethodHandle SET_DATA = NativeSymbolLookup.load("g_object_set_data",
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS));
        static final MethodHandle GET_DATA = NativeSymbolLookup.load("g_object_get_data",
                FunctionDescriptor.of(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS));
    }
