package com.sun.glass.ui.gtk4.wrappers;

import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandle;

import static com.sun.glass.ui.gtk4.wrappers.NativeSymbolLookup.invokeInt;
import static com.sun.glass.ui.gtk4.wrappers.NativeSymbolLookup.invokePointer;
import static com.sun.glass.ui.gtk4.wrappers.NativeSymbolLookup.invokeVoid;

public class GdkPopup {

    public static final int GDK_GRAVITY_NORTH_WEST = 1;
    public static final int GDK_ANCHOR_FLIP_X = 1;
    public static final int GDK_ANCHOR_FLIP_Y = 1 << 1;
    public static final int GDK_ANCHOR_SLIDE_X = 1 << 2;
    public static final int GDK_ANCHOR_SLIDE_Y = 1 << 3;

    private final MemorySegment ptr;

    public GdkPopup(MemorySegment ptr) {
        this.ptr = ptr;
    }

    public MemorySegment getPointer() {
        return ptr;
    }

    public boolean isNull() {
        return ptr == null || ptr.address() == 0;
    }

    public static MemorySegment layoutNew(int anchorX, int anchorY) {
        if (H.LAYOUT_NEW == null) {
            return MemorySegment.NULL;
        }
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment rect = GdkRectangle.allocate(arena, anchorX, anchorY, 1, 1);
            return invokePointer(H.LAYOUT_NEW, rect, GDK_GRAVITY_NORTH_WEST, GDK_GRAVITY_NORTH_WEST);
        }
    }

    public static void layoutSetOffset(MemorySegment layout, int dx, int dy) {
        if (H.LAYOUT_SET_OFFSET != null) {
            invokeVoid(H.LAYOUT_SET_OFFSET, layout, dx, dy);
        }
    }

    public static void layoutSetAnchorHints(MemorySegment layout, int hints) {
        if (H.LAYOUT_SET_ANCHOR_HINTS != null) {
            invokeVoid(H.LAYOUT_SET_ANCHOR_HINTS, layout, hints);
        }
    }

    public static void layoutUnref(MemorySegment layout) {
        if (H.LAYOUT_UNREF != null) {
            invokeVoid(H.LAYOUT_UNREF, layout);
        }
    }

    public boolean present(int width, int height, MemorySegment layout) {
        if (H.PRESENT == null) {
            return false;
        }
        return invokeInt(H.PRESENT, ptr, width, height, layout) != 0;
    }

    private static final class H {
        static final MethodHandle PRESENT = NativeSymbolLookup.loadOptional("gdk_popup_present",
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS,
                        ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.ADDRESS));
        static final MethodHandle LAYOUT_NEW = NativeSymbolLookup.loadOptional("gdk_popup_layout_new",
                FunctionDescriptor.of(ValueLayout.ADDRESS, ValueLayout.ADDRESS,
                        ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
        static final MethodHandle LAYOUT_SET_OFFSET = NativeSymbolLookup.loadOptional("gdk_popup_layout_set_offset",
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
        static final MethodHandle LAYOUT_SET_ANCHOR_HINTS =
                NativeSymbolLookup.loadOptional("gdk_popup_layout_set_anchor_hints",
                        FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.JAVA_INT));
        static final MethodHandle LAYOUT_UNREF = NativeSymbolLookup.loadOptional("gdk_popup_layout_unref",
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS));
    }
}

