package com.sun.glass.ui.gtk4;

import com.sun.glass.events.KeyEvent;
import com.sun.glass.ui.Application;
import com.sun.glass.ui.CommonDialogs.ExtensionFilter;
import com.sun.glass.ui.CommonDialogs.FileChooserResult;
import com.sun.glass.ui.Cursor;
import com.sun.glass.ui.GlassRobot;
import com.sun.glass.ui.Pixels;
import com.sun.glass.ui.Screen;
import com.sun.glass.ui.Size;
import com.sun.glass.ui.Timer;
import com.sun.glass.ui.View;
import com.sun.glass.ui.Window;
import com.sun.glass.ui.gtk4.wrappers.GLib;
import com.sun.glass.ui.gtk4.wrappers.GObject;
import com.sun.glass.ui.gtk4.wrappers.GdkDisplay;
import com.sun.glass.ui.gtk4.wrappers.GdkMonitor;
import com.sun.glass.ui.gtk4.wrappers.Gtk;
import com.sun.glass.ui.gtk4.wrappers.GtkSettings;

import java.io.File;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandles;
import java.nio.ByteBuffer;
import java.nio.IntBuffer;
import java.util.LinkedList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public final class Gtk4Application extends Application {

    private static final Gtk4Log.Category SCREEN = Gtk4Log.Category.SCREEN;
    private static final int GDK_LOCK_MASK = 1 << 1;
    private static final int GDK_MOD2_MASK = 1 << 4;
    private static final MethodHandles.Lookup LOOKUP = MethodHandles.lookup();

    private final ReentrantLock queueLock = new ReentrantLock();
    private final Condition queueCond = queueLock.newCondition();
    private final LinkedList<Runnable> runnableQueue = new LinkedList<>();
    private final LinkedList<Object[]> nestedLoops = new LinkedList<>();
    private final Arena appArena = Arena.ofAuto();
    private volatile boolean running;

    private Thread eventThread;

    public Gtk4Application() {

    }

    private static final int MIN_GTK_MAJOR = 4;
    private static final int MIN_GTK_MINOR = 14;

    // ...existing code...

    @Override
    protected void runLoop(final Runnable launchable) {
        running = true;
        final Thread toolkitThread = new Thread(() -> {
            Gtk.init();
            checkGtkVersion();

            connectMonitorSignals();

            processRunnableQueue();
            while (running) {
                GLib.mainContextIteration(true);

                processRunnableQueue();

                while (GLib.mainContextPending()) {
                    GLib.mainContextIteration(false);
                }
            }
        }, "Gtk4NativeMainLoopThread");

        eventThread = toolkitThread;
        setEventThread(toolkitThread);

        _invokeLater(launchable);

        toolkitThread.start();
    }

    @Override
    protected void finishTerminating() {
        running = false;
        GLib.mainContextWakeup();
        setEventThread(null);
        super.finishTerminating();
    }

    @Override
    public boolean shouldUpdateWindow() {
        return true;
    }

    @Override
    protected void _invokeLater(Runnable runnable) {
        queueLock.lock();
        try {
            runnableQueue.add(runnable);
            queueCond.signal();
        } finally {
            queueLock.unlock();
        }
        GLib.mainContextWakeup();
    }

    @Override
    protected void _invokeAndWait(Runnable runnable) {
        if (Thread.currentThread() == eventThread) {
            runnable.run();
            return;
        }
        final CountDownLatch latch = new CountDownLatch(1);
        _invokeLater(() -> {
            try {
                runnable.run();
            } finally {
                latch.countDown();
            }
        });
        try {
            latch.await();
        } catch (InterruptedException e) {
            // Fail silently
        }
    }

    private boolean hasQueuedRunnables() {
        queueLock.lock();
        try {
            return !runnableQueue.isEmpty();
        } finally {
            queueLock.unlock();
        }
    }

    private void processRunnableQueue() {
        LinkedList<Runnable> toRun;
        queueLock.lock();
        try {
            if (runnableQueue.isEmpty()) {
                return;
            }
            toRun = new LinkedList<>(runnableQueue);
            runnableQueue.clear();
        } finally {
            queueLock.unlock();
        }
        for (Runnable r : toRun) {
            try {
                r.run();
            } catch (Throwable t) {
                t.printStackTrace();
            }
        }
    }

    @Override
    protected Object _enterNestedEventLoop() {
        Object[] retHolder = new Object[1];
        CountDownLatch latch = new CountDownLatch(1);
        nestedLoops.push(new Object[] {retHolder, latch});

        while (latch.getCount() > 0) {
            GLib.mainContextIteration(true);
            processRunnableQueue();
            while (GLib.mainContextPending()) {
                GLib.mainContextIteration(false);
            }
        }

        return retHolder[0];
    }

    @Override
    protected void _leaveNestedEventLoop(Object retValue) {
        if (!nestedLoops.isEmpty()) {
            Object[] top = nestedLoops.pop();
            ((Object[]) top[0])[0] = retValue;
            ((CountDownLatch) top[1]).countDown();
        }
        GLib.mainContextWakeup();
    }

