    private void connectMonitorSignals() {
        GdkDisplay display = GdkDisplay.getDefault();
        if (display.getPointer() == null || display.getPointer().address() == 0) {
            return;
        }
        MemorySegment monitorsModel = display.getMonitorsModel();
        if (monitorsModel == null || monitorsModel.address() == 0) {
            return;
        }

        GObject.connect(monitorsModel, "items-changed", LOOKUP, this, "onMonitorsChanged",
                FunctionDescriptor.ofVoid(
                        ValueLayout.ADDRESS,
                        ValueLayout.JAVA_INT,
                        ValueLayout.JAVA_INT,
                        ValueLayout.JAVA_INT,
                        ValueLayout.ADDRESS),
                appArena);

        connectPerMonitorSignals(display);
    }

    private void connectPerMonitorSignals(GdkDisplay display) {
        var descriptor = FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS);
        int count = display.getMonitorCount();
        for (int i = 0; i < count; i++) {
            GdkMonitor monitor = display.getMonitorAt(i);
            if (monitor == null) {
                continue;
            }
            GObject.connect(monitor.getPointer(), "invalidate", LOOKUP, this,
                    "onMonitorInvalidated", descriptor, appArena);
            GObject.unref(monitor.getPointer());
        }
    }

    @SuppressWarnings("unused")
    void onMonitorsChanged(MemorySegment model, int position, int removed, int added,
                           MemorySegment userData) {
        // Reconnect per-monitor signals since the set of monitors changed.
        connectPerMonitorSignals(GdkDisplay.getDefault());
        Screen.notifySettingsChanged();
    }

    @SuppressWarnings("unused")
    void onMonitorInvalidated(MemorySegment monitor, MemorySegment userData) {
        Screen.notifySettingsChanged();
    }

    @Override
    protected double staticScreen_getVideoRefreshPeriod() {
        GdkDisplay display = GdkDisplay.getDefault();

        if (display.getPointer() == null || display.getPointer().address() == 0) {
            return 0.0;
        }

        int count = display.getMonitorCount();
        if (count <= 0) {
            return 0.0;
        }

        GdkMonitor monitor = display.getMonitorAt(0);
        if (monitor == null) {
            return 0.0;
        }

        int refreshMHz = monitor.getRefreshRate();

        GObject.unref(monitor.getPointer());

        if (refreshMHz <= 0) {
            return 0.0;
        }

        return 1_000_000.0 / refreshMHz;
    }

    @Override
    protected Screen[] staticScreen_getScreens() {
        GdkDisplay display = GdkDisplay.getDefault();
        if (display.getPointer() == null || display.getPointer().address() == 0) {
            Gtk4Log.log(SCREEN, "staticScreen_getScreens: no display");
            return new Screen[0];
        }

        int count = display.getMonitorCount();
        Gtk4Log.log(SCREEN, "staticScreen_getScreens: monitorCount=%d", count);
        if (count <= 0) {
            return new Screen[0];
        }

        Screen[] screens = new Screen[count];
        for (int i = 0; i < count; i++) {
            GdkMonitor gdkMonitor = display.getMonitorAt(i);
            if (gdkMonitor == null) {
                continue;
            }

            int[] geom = gdkMonitor.getGeometry();
            int x = geom[0];
            int y = geom[1];
            int w = geom[2];
            int h = geom[3];
            float scale = (float) gdkMonitor.getScale();
            if (scale < 1.0f) {
                scale = 1.0f;
            }

            int mmW = gdkMonitor.getWidthMm();
            int mmH = gdkMonitor.getHeightMm();
            int dpiX, dpiY;
            if (mmW <= 0 || mmH <= 0) {
                dpiX = dpiY = 96;
            } else {
                dpiX = (w * 254) / (mmW * 10);
                dpiY = (h * 254) / (mmH * 10);
            }

            // Unref the monitor (g_list_model_get_item returns a reference)
            GObject.unref(gdkMonitor.getPointer());

            Gtk4Log.log(SCREEN, "screen[%d]: x=%d y=%d %dx%d scale=%.2f dpi=%dx%d mmW=%d mmH=%d",
                    i, x, y, w, h, scale, dpiX, dpiY, mmW, mmH);

            screens[i] = new Screen(
                    i,      // nativePtr (monitor index)
                    32,     // depth — GTK4 always uses ARGB
                    x, y,   // x, y (logical)
                    w, h,   // width, height (logical)
                    x, y,   // platformX, platformY (GTK4 coords are logical)
                    w, h,   // platformWidth, platformHeight (logical)
                    x, y,   // visibleX, visibleY (no work area API on Wayland)
                    w, h,   // visibleWidth, visibleHeight (logical)
                    dpiX, dpiY, // resolutionX, resolutionY
                    // platformScale = 1.0: GTK4 coordinates are already in logical
                    // (CSS) pixels — Glass must not apply any further scaling to
                    // sizes, positions, or mouse coordinates.
                    1.0f, 1.0f,   // platformScaleX, platformScaleY
                    // outputScale = actual display scale: tells Prism to render the
                    // backbuffer at physical pixel resolution so the DMA-BUF texture
                    // matches the display's physical pixels (1:1 → crisp on HiDPI).
                    scale, scale  // outputScaleX, outputScaleY
            );
        }
        return screens;
    }

