    @Override
    protected int _isKeyLocked(int keyCode) {
        int modState = GdkDisplay.getDefault().getModifierState();
        if (modState == GdkDisplay.UNKNOWN_MODIFIER_STATE) {
            return KeyEvent.KEY_LOCK_UNKNOWN;
        }
        return switch (keyCode) {
            case KeyEvent.VK_CAPS_LOCK -> (modState & GDK_LOCK_MASK) != 0 ? KeyEvent.KEY_LOCK_ON : KeyEvent.KEY_LOCK_OFF;
            case KeyEvent.VK_NUM_LOCK  -> (modState & GDK_MOD2_MASK) != 0 ? KeyEvent.KEY_LOCK_ON : KeyEvent.KEY_LOCK_OFF;
            default                    -> KeyEvent.KEY_LOCK_UNKNOWN;
        };
    }
