    private void checkGtkVersion() {
        int major = Gtk.getMajorVersion();
        int minor = Gtk.getMinorVersion();
        int micro = Gtk.getMicroVersion();
        if (major < MIN_GTK_MAJOR || (major == MIN_GTK_MAJOR && minor < MIN_GTK_MINOR)) {
            throw new UnsupportedOperationException(
                    "GTK %d.%d.%d is not supported. Minimum required version is %d.%d.0"
                            .formatted(major, minor, micro, MIN_GTK_MAJOR, MIN_GTK_MINOR));
        }
    }

