import com.sun.glass.ui.Pixels;
import com.sun.glass.ui.gtk4.wrappers.GBytes;
import com.sun.glass.ui.gtk4.wrappers.GObject;
import com.sun.glass.ui.gtk4.wrappers.GdkDisplay;
import com.sun.glass.ui.gtk4.wrappers.GdkMemoryTexture;
import com.sun.glass.ui.gtk4.wrappers.GtkDmabufTextureBuilder;
import com.sun.glass.ui.gtk4.wrappers.GtkGraphicsOffload;
import com.sun.glass.ui.gtk4.wrappers.GtkPicture;
import com.sun.glass.ui.gtk4.wrappers.GtkWidget;
import com.sun.prism.es2.DmaBufHelper;

import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.nio.ByteBuffer;
import java.nio.IntBuffer;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

final class Gtk4Compositor {

    private static final int SLOT_COUNT = 3;
    private static final Arena DESTROY_CALLBACK_ARENA = Arena.global();
    private static final Object GBM_DEVICE_LOCK = new Object();
    private static volatile boolean gbmUnsupported;
    private static volatile long sharedGbmDevice;

    private final AtomicReference<PublishedFrame> pendingFrame = new AtomicReference<>();
    private final AtomicBoolean updateScheduled = new AtomicBoolean(false);
    private final GtkPicture picture;
    private final GtkWidget widget;
    private final boolean composited;
    private final MemorySegment destroyNotifyCb;
    private final Runnable updateRunnable;
    private BufferSlot[] slots;        // [0], [1], [2] (round-robin each frame)
    private int backIndex = 0;         // index of the current back buffer
    private int lastAcquiredIndex = -1;
    private int allocatedWidth;        // width of the allocated buffers
    private int allocatedHeight;       // height of the allocated buffers
    private volatile int displayedSlotIndex = -1;
    private volatile int retiringSlotIndex = -1;
    private MemorySegment[] slotTextures;
    private GdkMemoryTexture softwareTexture;

    /**
     * Creates the DMA-BUF compositor. Builds the widget hierarchy:
     * GtkGraphicsOffload &rarr; GtkPicture.
     * <p>
     * GtkPicture is used because GtkGraphicsOffload inspects its child's
     * render nodes for {@code GdkDmabufTexture} entries to offload to a
     * Wayland subsurface. GtkPicture produces exactly that render node
     * when its paintable is a GdkTexture.
     * <p>
     * Uses {@code GTK_CONTENT_FIT_FILL} so the rendered texture always
     * fills the widget area without any transforms.  This is critical for
     * {@code GtkGraphicsOffload}: the default {@code CONTAIN} mode wraps
     * the texture in a scale/translate {@code TransformNode} that
     * GtkGraphicsOffload (GTK 4.14) cannot reliably offload.
     */
    Gtk4Compositor() {
        this.picture = GtkPicture.create();

        picture.setContentFit(GtkPicture.GTK_CONTENT_FIT_FILL);
        picture.setCanShrink(true);

        if (isAvailable()) {
            this.composited = true;
            GtkGraphicsOffload offloadRef = GtkGraphicsOffload.create(picture);
            offloadRef.setEnabled(GtkGraphicsOffload.GTK_GRAPHICS_OFFLOAD_ENABLED);
            this.widget = offloadRef;
        } else {
            this.composited = false;
            this.widget = picture;
        }

        widget.setHExpand(true);
        widget.setVExpand(true);
        widget.setHAlign(GtkWidget.GTK_ALIGN_FILL);
        widget.setVAlign(GtkWidget.GTK_ALIGN_FILL);

        MemorySegment cb;
        try {
            cb = Linker.nativeLinker().upcallStub(
                    MethodHandles.lookup().bind(this, "onTextureDestroyed",
                            MethodType.methodType(void.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS),
                    DESTROY_CALLBACK_ARENA);
        } catch (NoSuchMethodException | IllegalAccessException e) {
            cb = MemorySegment.NULL;
        }
        this.destroyNotifyCb = composited ? cb : MemorySegment.NULL;

        this.updateRunnable = this::updatePictureOnGtkThread;
    }

    private static long getGbmDevice() {
        long dev = sharedGbmDevice;
        if (dev != 0) {
            return dev;
        }
        synchronized (GBM_DEVICE_LOCK) {
            dev = sharedGbmDevice;
            if (dev != 0) {
                return dev;
            }
            dev = DmaBufHelper.nCreateGbmDevice();
            sharedGbmDevice = dev;
            return dev;
        }
    }

    private static BufferSlot allocateSlot(long gbmDevice,
                                           int width, int height) {
        long nativeSlot = DmaBufHelper.nCreateSlot(gbmDevice, width, height);
        if (nativeSlot == 0) {
            System.err.println("Gtk4Compositor: Failed to create native DMA-BUF slot");
            return null;
        }

        int fd = DmaBufHelper.nGetSlotFd(nativeSlot);
        int stride = DmaBufHelper.nGetSlotStride(nativeSlot);
        int offset = DmaBufHelper.nGetSlotOffset(nativeSlot);
        int fourcc = DmaBufHelper.nGetSlotFourcc(nativeSlot);
        long modifier = DmaBufHelper.nGetSlotModifier(nativeSlot);

        return new BufferSlot(nativeSlot, fd, stride, offset, fourcc, modifier);
    }

    static boolean isAvailable() {
        boolean graphicsOffloadAvailable = GtkGraphicsOffload.isAvailable();
        boolean dmabufTextureBuilderAvailable = GtkDmabufTextureBuilder.isAvailable();

        boolean available = graphicsOffloadAvailable
                && dmabufTextureBuilderAvailable;

        System.out.println("Gtk4Compositor.isAvailable: "
                + "GtkGraphicsOffload=" + graphicsOffloadAvailable
                + " GtkDmabufTextureBuilder=" + dmabufTextureBuilderAvailable
                + " => available=" + available);

        return available;
    }


    public GtkWidget getWidget() {
        return widget;
    }


    public void publishPixels(Pixels pixels) {
        if (pixels == null) {
            return;
        }
        int width = pixels.getWidth();
        int height = pixels.getHeight();
        if (width <= 0 || height <= 0) {
            return;
        }

        int stride = width * 4;
        long dataSize = (long) stride * height;
        int pixelCount = width * height;

        try (Arena arena = Arena.ofConfined()) {
            MemorySegment nativeData = arena.allocate(dataSize);

            Object pixelBuf = pixels.getPixels();
            if (pixelBuf instanceof IntBuffer ints) {
                ints.rewind();
                if (ints.hasArray()) {
                    MemorySegment.copy(ints.array(), ints.arrayOffset(),
                            nativeData, ValueLayout.JAVA_INT, 0, pixelCount);
                } else {
                    MemorySegment srcSegment = MemorySegment.ofBuffer(ints);
                    MemorySegment.copy(srcSegment, 0, nativeData, 0, dataSize);
                }
            } else if (pixelBuf instanceof ByteBuffer bb) {
                bb.rewind();
                if (bb.hasArray()) {
                    MemorySegment.copy(bb.array(), bb.arrayOffset(),
                            nativeData, ValueLayout.JAVA_BYTE, 0, (int) dataSize);
                } else {
                    MemorySegment srcSegment = MemorySegment.ofBuffer(bb);
                    MemorySegment.copy(srcSegment, 0, nativeData, 0, dataSize);
                }
            } else {
                return;
            }

            GBytes gbytes = GBytes.create(nativeData, dataSize);
            GdkMemoryTexture memTex = GdkMemoryTexture.create(
                    width, height,
                    GdkMemoryTexture.GDK_MEMORY_B8G8R8A8_PREMULTIPLIED,
                    gbytes, stride);
            gbytes.unref();

            if (memTex.isNull()) {
                return;
            }

            picture.setPaintable(memTex);

            if (softwareTexture != null && !softwareTexture.isNull()) {
                softwareTexture.unref();
            }
            softwareTexture = memTex;
        }
    }

    private boolean ensureBuffers(long gbmDevice,
                                  int width, int height) {
        if (slots != null && allocatedWidth == width && allocatedHeight == height) {
            return true;
        }

        // Destroy old slots and textures if size changed
        if (slots != null) {
            for (BufferSlot slot : slots) {
                if (slot != null) {
                    slot.destroy();
                }
            }
            slots = null;
        }
        if (slotTextures != null) {
            for (int i = 0; i < slotTextures.length; i++) {
                if (slotTextures[i] != null && slotTextures[i].address() != 0) {
                    GObject.unref(slotTextures[i]);
                    slotTextures[i] = null;
                }
            }
            slotTextures = null;
        }

        BufferSlot[] newSlots = new BufferSlot[SLOT_COUNT];
        for (int i = 0; i < SLOT_COUNT; i++) {
            newSlots[i] = allocateSlot(gbmDevice, width, height);
            if (newSlots[i] == null) {
                // Clean up already-allocated slots
                for (int j = 0; j < i; j++) {
                    if (newSlots[j] != null) {
                        newSlots[j].destroy();
                    }
                }
                return false;
            }
        }

        slots = newSlots;
        slotTextures = new MemorySegment[SLOT_COUNT];
        backIndex = 0;
        displayedSlotIndex = -1;
        retiringSlotIndex = -1;
        allocatedWidth = width;
        allocatedHeight = height;
        return true;
    }

    boolean publishFrame(int textureId, int width, int height) {
        if (!composited || gbmUnsupported || width <= 0 || height <= 0) {
            return false;
        }

        long gbmDevice = getGbmDevice();
        if (gbmDevice == 0) {
            gbmUnsupported = true;
            System.err.println("Gtk4Compositor: GBM device unavailable");
            return false;
        }

        if (!ensureBuffers(gbmDevice, width, height)) {
            gbmUnsupported = true;
            return false;
        }

        if (lastAcquiredIndex < 0 || lastAcquiredIndex >= SLOT_COUNT) {
            return false;
        }

        BufferSlot back = slots[lastAcquiredIndex];
        int chosenIndex = lastAcquiredIndex;
        lastAcquiredIndex = -1;

        DmaBufHelper.nFenceSync(back.nativeSlot);

        int dupFd = DmaBufHelper.nDupFd(back.fd);
        if (dupFd < 0) {
            System.err.println("Gtk4Compositor: Failed to dup DMA-BUF fd");
            return false;
        }

        back.busy = true;

        PublishedFrame newFrame = new PublishedFrame(
                dupFd, back.stride, back.offset, back.fourcc, back.modifier,
                width, height, chosenIndex);

        PublishedFrame oldFrame = pendingFrame.getAndSet(newFrame);
        if (oldFrame != null) {
            releaseSlotBusy(oldFrame.slotIndex());
            DmaBufHelper.nCloseFd(oldFrame.fd());
        }

        backIndex = (chosenIndex + 1) % SLOT_COUNT;

        if (updateScheduled.compareAndSet(false, true)) {
            Application.invokeLater(updateRunnable);
        }
        return true;
    }

    int acquireBackBuffer(int width, int height) {
        if (!composited || gbmUnsupported || width <= 0 || height <= 0) {
            return -1;
        }

        long gbmDevice = getGbmDevice();
        if (gbmDevice == 0) {
            gbmUnsupported = true;
            return -1;
        }

        if (!ensureBuffers(gbmDevice, width, height)) {
            gbmUnsupported = true;
            return -1;
        }

        for (int i = 0; i < SLOT_COUNT; i++) {
            int idx = (backIndex + i) % SLOT_COUNT;
            if (!slots[idx].busy) {
                lastAcquiredIndex = idx;
                return idx;
            }
        }
        return -1;
    }

    long getSlotNativePtr(int slotIndex) {
        if (slots == null || slotIndex < 0 || slotIndex >= slots.length) {
            return 0;
        }
        return slots[slotIndex].nativeSlot;
    }

    /**
     * Called on the GTK main thread to update the GtkPicture with the latest frame.
     * <p>
     * Slot lifecycle with triple buffering:
     * <ol>
     *   <li>Release the <b>retiring</b> slot (it was displayed 2 updates ago —
     *       the Wayland compositor has had a full frame to release it).</li>
     *   <li>The <b>currently displayed</b> slot becomes the <b>retiring</b> slot.</li>
     *   <li>The <b>new frame's</b> slot becomes the <b>displayed</b> slot.</li>
     * </ol>
     * This gives each buffer at least two full GTK update cycles between the
     * time it stops being on the GtkPicture and the time the render thread
     * may reuse it — enough for the Wayland compositor to process
     * {@code wl_buffer.release}.
     */
    private void updatePictureOnGtkThread() {
        updateScheduled.set(false);
        PublishedFrame frame = pendingFrame.getAndSet(null);
        if (frame == null) {
            return;
        }

        GtkDmabufTextureBuilder builder = GtkDmabufTextureBuilder.create();
        if (builder.isNull()) {
            DmaBufHelper.nCloseFd(frame.fd());
            releaseSlotBusy(frame.slotIndex());
            return;
        }

        builder.setDisplay(GdkDisplay.getDefault());
        builder.setWidth(frame.width());
        builder.setHeight(frame.height());
        builder.setFourcc(frame.fourcc());
        builder.setModifier(frame.modifier());
        builder.setNPlanes(1);
        builder.setFd(0, frame.fd());
        builder.setStride(0, frame.stride());
        builder.setOffset(0, frame.offset());

        MemorySegment destroyData = MemorySegment.ofAddress(((long) frame.fd()) + 1L);
        MemorySegment texture = builder.build(destroyNotifyCb, destroyData);

        GObject.unref(builder.getPointer());

        if (texture == null || texture.address() == 0) {
            System.err.println("Gtk4Compositor: Failed to build GdkDmabufTexture " +
                    "(fourcc=0x" + Integer.toHexString(frame.fourcc()) +
                    " modifier=0x" + Long.toHexString(frame.modifier()) + ")");
            DmaBufHelper.nCloseFd(frame.fd());
            releaseSlotBusy(frame.slotIndex());
            return;
        }

        // ── Step 1: Release the RETIRING slot ──────────────────────────
        // This slot was displayed 2 updates ago.  The Wayland compositor
        // has had a full frame clock cycle to send wl_buffer.release.
        // Release the GBM BO *and* the GdkDmabufTexture (wl_buffer) together
        // so both are freed at the same safe point.
        int retiring = retiringSlotIndex;
        if (retiring >= 0) {
            releaseSlotBusy(retiring);
            releaseSlotTexture(retiring);
        }

        // ── Step 2: Displayed → Retiring ───────────────────────────────
        retiringSlotIndex = displayedSlotIndex;

        // ── Step 3: Set new paintable ──────────────────────────────────
        // gtk_picture_set_paintable internally calls gtk_widget_queue_resize
        // (which implies a queue_draw), so no explicit queue_draw needed.
        picture.setPaintable(texture);

        // ── Step 4: New frame → Displayed ──────────────────────────────
        displayedSlotIndex = frame.slotIndex();

        // ── Step 5: Store texture reference for this slot ──────────────
        // Keeps the GdkDmabufTexture (and its wl_buffer) alive until the
        // slot's busy flag is cleared in Step 1 of a future update.
        MemorySegment[] textures = slotTextures;
        if (textures != null) {
            textures[frame.slotIndex()] = texture;
        }
    }

    private void releaseSlotBusy(int slotIndex) {
        BufferSlot[] currentSlots = slots;
        if (currentSlots != null && slotIndex >= 0
                && slotIndex < currentSlots.length
                && currentSlots[slotIndex] != null) {
            currentSlots[slotIndex].busy = false;
        }
    }

    private void releaseSlotTexture(int slotIndex) {
        MemorySegment[] textures = slotTextures;
        if (textures != null && slotIndex >= 0 && slotIndex < textures.length) {
            MemorySegment tex = textures[slotIndex];
            if (tex != null && tex.address() != 0) {
                GObject.unref(tex);
            }
            textures[slotIndex] = null;
        }
    }

    @SuppressWarnings("unused")
    void onTextureDestroyed(MemorySegment data) {
        int fd = (int) (data.address() - 1L);
        if (fd >= 0) {
            DmaBufHelper.nCloseFd(fd);
        }
    }

    public void dispose() {
        // Clear the GtkPicture so GTK drops its reference to the current texture
        picture.setPaintable(MemorySegment.NULL);

        // Release the software-fallback texture (if used)
        if (softwareTexture != null && !softwareTexture.isNull()) {
            softwareTexture.unref();
            softwareTexture = null;
        }

        PublishedFrame frame = pendingFrame.getAndSet(null);
        if (frame != null) {
            DmaBufHelper.nCloseFd(frame.fd());
        }

        // Release all per-slot textures (GdkDmabufTexture / wl_buffer)
        if (slotTextures != null) {
            for (int i = 0; i < slotTextures.length; i++) {
                if (slotTextures[i] != null && slotTextures[i].address() != 0) {
                    GObject.unref(slotTextures[i]);
                    slotTextures[i] = null;
                }
            }
            slotTextures = null;
        }

        displayedSlotIndex = -1;
        retiringSlotIndex = -1;

        if (slots != null) {
            for (BufferSlot slot : slots) {
                if (slot != null) {
                    slot.destroy();
                }
            }
            slots = null;
        }
    }

    boolean publishRenderedTexture(int textureId, int width, int height) {
        return publishFrame(textureId, width, height);
    }

    int acquireExternalBackBuffer(int width, int height) {
        return acquireBackBuffer(width, height);
    }

    boolean isComposited() {
        return composited;
    }

    /**
     * Holds all GPU resources for one buffer slot in the triple-buffer scheme.
     * Resources are allocated once (per size) and reused across frames.
     * <p>
     * The GBM buffer object, EGLImage, GL texture, and FBO are managed
     * in native code (via {@link DmaBufHelper}); this Java-side record
     * keeps DMA-BUF metadata for the GTK presentation layer.
     */
    private static final class BufferSlot {
        final long nativeSlot;
        final int fd;
        final int stride;
        final int offset;
        final int fourcc;
        final long modifier;

        volatile boolean busy;

        BufferSlot(long nativeSlot, int fd,
                   int stride, int offset, int fourcc, long modifier) {
            this.nativeSlot = nativeSlot;
            this.fd = fd;
            this.stride = stride;
            this.offset = offset;
            this.fourcc = fourcc;
            this.modifier = modifier;
        }

        void destroy() {
            if (nativeSlot != 0) {
                DmaBufHelper.nDestroySlot(nativeSlot);
            }
        }
    }

    private record PublishedFrame(
            int fd,            // DMA-BUF file descriptor (dup'd — will be closed by GDK)
            int stride,        // row stride in bytes
            int offset,        // offset to first pixel
            int fourcc,        // DRM pixel format
            long modifier,     // DRM format modifier
            int width,         // buffer width in pixels
            int height,        // buffer height in pixels
            int slotIndex      // index into slots[] that this frame was rendered to
    ) {
    }
}

