package com.sun.glass.ui.gtk4;

import com.sun.glass.ui.Pixels;

import java.nio.ByteBuffer;
import java.nio.IntBuffer;

/**
 * GTK4 Pixels implementation. Pure Java — no native calls needed.
 */
final class Gtk4Pixels extends Pixels {

    Gtk4Pixels(int width, int height, ByteBuffer data) {
        super(width, height, data);
    }

    Gtk4Pixels(int width, int height, ByteBuffer data, float scalex, float scaley) {
        super(width, height, data, scalex, scaley);
    }

    Gtk4Pixels(int width, int height, IntBuffer data) {
        super(width, height, data);
    }

    Gtk4Pixels(int width, int height, IntBuffer data, float scalex, float scaley) {
        super(width, height, data, scalex, scaley);
    }

    @Override
    protected void _fillDirectByteBuffer(ByteBuffer bb) {
        if (this.bytes != null) {
            this.bytes.rewind();
            bb.put(this.bytes);
            this.bytes.rewind();
        } else {
            this.ints.rewind();
            for (int i = 0; i < this.ints.capacity(); i++) {
                int data = this.ints.get();
                bb.put((byte) ((data) & 0xff));
                bb.put((byte) ((data >> 8) & 0xff));
                bb.put((byte) ((data >> 16) & 0xff));
                bb.put((byte) ((data >> 24) & 0xff));
            }
            this.ints.rewind();
        }
    }

    /**
     * No-op in GTK4.  In GTK3, native C++ code called {@code Pixels.attachData(ptr)}
     * which dispatched here to create a {@code GdkPixbuf} (with BGRA→RGBA conversion)
     * for icons, cursors, clipboard images, and drag-and-drop.
     * <p>
     * In GTK4 via FFI there is no native C++ code to call {@code attachData}, so this
     * callback is never invoked.  All pixel conversions are done directly in Java
     * (e.g. {@code Gtk4Window._setIcon} creates a {@code GdkMemoryTexture} from the
     * IntBuffer without needing the {@code GdkPixbuf} round-trip).  GTK4's
     * {@code GdkMemoryTexture} accepts BGRA natively ({@code GDK_MEMORY_B8G8R8A8_PREMULTIPLIED}),
     * eliminating the BGRA→RGBA conversion that GTK3's {@code convert_BGRA_to_RGBA} performed.
     */
    @Override
    protected void _attachInt(long ptr, int w, int h, IntBuffer ints, int[] array, int offset) {
        // No-op: see class-level Javadoc above
    }

    /** See {@link #_attachInt} — same rationale applies to byte-buffer pixels. */
    @Override
    protected void _attachByte(long ptr, int w, int h, ByteBuffer bytes, byte[] array, int offset) {
        // No-op: see _attachInt Javadoc
    }
}

