package com.sun.glass.ui.gtk4;


import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.util.HashSet;
import java.util.Set;

/**
 * Java-side equivalent of the C++ {@code WindowContext} class from {@code glass_window.cpp},
 * but targeting <b>GTK4</b> and using the Foreign Function &amp; Memory API (Panama FFI)
 * instead of JNI.
 * <p>
 * This class manages all GTK4 window types:
 * <ul>
 *   <li><b>Normal / Utility / Titled / Extended / Transparent</b> — backed by a {@code GtkWindow}</li>
 *   <li><b>Popup</b> — backed by a {@code GtkPopover} attached to the owner's widget</li>
 * </ul>
 * <p>
 * All window types use the DMA-BUF compositor path ({@link Gtk4DmaBufCompositor} /
 * {@code GtkGraphicsOffload}) for zero-copy presentation to the Wayland compositor.
 *
 * <h2>GTK3 → GTK4 changes</h2>
 * <ul>
 *   <li>No direct {@code GdkWindow} manipulation – use {@code GtkWindow} widget APIs</li>
 *   <li>Event delivery via event controllers, not {@code GdkEvent*} callbacks</li>
 *   <li>{@code GdkSurface} replaces {@code GdkWindow} for native handle access</li>
 *   <li>Popup windows use {@code GtkPopover} instead of {@code GTK_WINDOW_POPUP}</li>
 *   <li>No {@code gdk_window_set_keep_above} – must use window manager hints or
 *       X11-specific paths</li>
 * </ul>
 */
final class Gtk4WindowContext {


    // =========================================================================
    // Constants (mirrors of C++ constants)
    // =========================================================================

    static final int DEFAULT_WIDTH = 320;
    static final int DEFAULT_HEIGHT = 200;
    static final int MAX_WINDOW_SIZE = 32767;
    static final int RESIZE_BORDER_WIDTH = 5;
    private static final double USE_DEFAULT_HEADER_BUTTON_SIZE = -1;
    private static final int HT_CAPTION = 1;

    /**
     * Whether the display-level CSS for transparent popups has been registered.
     */
    private static boolean popupCssRegistered;
    private final Gtk4Window jfxWindow;         // The Glass Window (Java)

    // =========================================================================
    // Window frame / type enums (matching the C++ enums)
    // =========================================================================
    private final MemorySegment gtkWindow;      // GtkWindow* (native) — NULL for POPUP
    private final MemorySegment gtkPopover;     // GtkPopover* (native) — NULL for non-POPUP
    private final Arena windowArena;            // Arena that owns callback stubs

    // =========================================================================
    // Instance state
    // =========================================================================
    private final boolean isAdwWindow;          // true when using AdwWindow
    /**
     * True when this is a POPUP window backed by a GtkPopover.
     */
    private final boolean isPopup;
    /**
     * DMA-BUF compositor for zero-copy presentation via GtkGraphicsOffload.
     */
    private final Gtk4DmaBufCompositor compositor;
    /**
     * Widget set as GtkWindow child; this is the source of View size.
     */
    private final MemorySegment childWidget;
    private final Set<Gtk4WindowContext> children = new HashSet<>();
    private final FrameType frameType;
    private final WindowType windowType;
    /**
     * CSD header bar for TITLED windows. Null for undecorated/popup windows.
     */
    private MemorySegment headerBar;
    /**
     * EXTENDED window root container (GtkOverlay) that hosts content + GtkWindowControls overlays.
     */
    private MemorySegment windowRootOverlay;
    /**
     * Native window controls used for EXTENDED windows (both decoration sides).
     */
    private MemorySegment nativeHeaderControlsStart;
    private MemorySegment nativeHeaderControlsEnd;
    /**
     * GdkSurface* obtained after the window is realized. Null until then.
     */
    private MemorySegment gdkSurface;
    private Gtk4WindowContext owner;
    private boolean visible;
    private boolean mapped;
    private boolean destroyed;
    private boolean disabled;
    private boolean onTop;
    private boolean resizable = true;
    private boolean mouseEntered;
    private boolean focusable = true;
    // Size tracking
    private int viewWidth = DEFAULT_WIDTH;
    private int viewHeight = DEFAULT_HEIGHT;
    private int windowWidth = DEFAULT_WIDTH;
    private int windowHeight = DEFAULT_HEIGHT;
    private int windowX = -1;
    private int windowY = -1;
    private int viewX;
    private int viewY;
    // Min/Max
    private int minWidth = 1, minHeight = 1;
    private int maxWidth = Integer.MAX_VALUE, maxHeight = Integer.MAX_VALUE;
    private int sysMinWidth = 1, sysMinHeight = 1;
    // Bounds type tracking
    private BoundsType widthType = BoundsType.UNKNOWN;
    private BoundsType heightType = BoundsType.UNKNOWN;
    private float gravityX, gravityY;
    // Last known mouse position (view-relative), used for scroll events
    // and absolute coordinate computation.
    private int lastMouseX, lastMouseY;
    /**
     * Preferred native header button height set by HeaderBar API.
     */
    private double prefHeaderButtonHeight = USE_DEFAULT_HEADER_BUTTON_SIZE;
    /**
     * Suppresses the matching release after a compositor-managed begin_move press.
     */
    private boolean suppressClickRelease;
    Gtk4WindowContext(Gtk4Window jfxWindow, Gtk4WindowContext owner,
                      FrameType frameType, WindowType windowType) {
        System.out.println("[Gtk4WindowContext] <init>: frameType=" + frameType
                + " windowType=" + windowType + " owner=" + (owner != null));
        this.jfxWindow = jfxWindow;
        this.owner = owner;
        this.frameType = frameType;
        this.windowType = windowType;
        this.windowArena = Arena.ofShared();
        this.isPopup = (windowType == WindowType.POPUP);

        // ─── Content area: GtkGraphicsOffload + GtkPicture ────────────
        if (Gtk4DmaBufCompositor.isAvailable()) {
            this.compositor = new Gtk4DmaBufCompositor();
            this.childWidget = compositor.getWidget();
        } else {
            System.err.println("Gtk4WindowContext: GtkGraphicsOffload not available, "
                    + "falling back to plain widget (no hardware rendering)");
            this.compositor = null;
            MemorySegment contentWidget = Native.Gtk.boxNew(Native.Gtk.GTK_ORIENTATION_VERTICAL, 0);
            Native.Gtk.widgetSetHExpand(contentWidget, true);
            Native.Gtk.widgetSetVExpand(contentWidget, true);
            this.childWidget = contentWidget;
        }

        if (isPopup) {
            // ── Popup path: GtkPopover ──────────────────────────────────
            // GtkPopover is the GTK4 replacement for GTK_WINDOW_POPUP.
            // It is parented on the owner's GtkWindow and positioned
            // relative to it via gtk_popover_set_pointing_to().
            this.gtkPopover = Native.Gtk.popoverNew();
            this.gtkWindow = MemorySegment.NULL;
            this.isAdwWindow = false;

            // Configure popover: no arrow, no autohide (JavaFX manages that)
            Native.Gtk.popoverSetHasArrow(gtkPopover, false);
            Native.Gtk.popoverSetAutohide(gtkPopover, false);
            Native.Gtk.popoverSetCascadePopdown(gtkPopover, false);
            Native.Gtk.popoverSetPosition(gtkPopover, Native.Gtk.GTK_POS_BOTTOM);

            // JavaFX renders its own popup content — the GTK popover must be
            // fully transparent with no borders, background or drop-shadow.
            // We add a custom CSS class and register a display-level provider
            // (the GTK4-correct approach, since per-widget style-context
            // providers are deprecated and do not reliably reach child nodes
            // such as "contents" and "arrow").
            Native.Gtk.widgetAddCssClass(gtkPopover, "jfx-popup");
            ensurePopupCssRegistered();

            // Set content
            Native.Gtk.popoverSetChild(gtkPopover, childWidget);

            // Parent to owner's GtkWindow.  Pointing-to coordinates are
            // relative to the GtkWindow widget, which in GTK4 CSD includes
            // the title bar area.
            if (owner != null) {
                owner.addChild(this);
                Native.Gtk.widgetSetParent(gtkPopover, owner.getGtkWindow());
            }
        } else {
            // ── GtkWindow path (normal / utility / titled / transparent) ─
            this.gtkPopover = MemorySegment.NULL;

            // Transparent windows must use plain GtkWindow (not AdwWindow) because
            // Adwaita applies opaque backgrounds and rounded corners that cannot
            // be fully overridden via CSS.
            if (frameType == FrameType.TRANSPARENT) {
                this.gtkWindow = Native.Gtk.windowNew();
                this.isAdwWindow = false;
            } else {
                // Prefer Adw.Window when libadwaita is available.
                this.gtkWindow = Native.Gtk.windowNewPreferred();
                this.isAdwWindow = Native.Gtk.isAdwWindowAvailable();
            }

            configureWindowContent(childWidget);

            // Set default size
            Native.Gtk.windowSetDefaultSize(gtkWindow, DEFAULT_WIDTH, DEFAULT_HEIGHT);

            // Set title (empty by default)
            setTitle("");

            // Owner relationship
            if (owner != null) {
                owner.addChild(this);
                Native.Gtk.windowSetTransientFor(gtkWindow, owner.gtkWindow);
                if (owner.effectiveOnTop()) {
                    onTop = true;
                }
            }
        }

        // Install event controllers on the content widget (not the window)
        installEventControllers();

        // Connect window/popover signals
        connectWindowSignals();
    }

    /**
     * Registers a display-level CSS provider (once) that strips all background,
     * border, shadow and rounded corners from GtkPopovers carrying the
     * {@code jfx-popup} CSS class.  JavaFX renders its own popup content, so
     * the native container must be fully transparent.
     */
    private static void ensurePopupCssRegistered() {
        if (popupCssRegistered) {
            return;
        }
        popupCssRegistered = true;

        String css =
                "popover.jfx-popup,"
                        + "popover.jfx-popup > contents,"
                        + "popover.jfx-popup > arrow {"
                        + "  background-color: transparent;"
                        + "  background: none;"
                        + "  border: none;"
                        + "  border-radius: 0;"
                        + "  box-shadow: none;"
                        + "  margin: 0;"
                        + "  padding: 0;"
                        + "  min-width: 0;"
                        + "  min-height: 0;"
                        + "}";

        MemorySegment provider = Native.Gtk.cssProviderNew();
        Native.Gtk.cssProviderLoadFromString(provider, css);

        // GTK_STYLE_PROVIDER_PRIORITY_USER = 800 — overrides Adwaita defaults
        MemorySegment display = Native.Gdk.displayGetDefault();
        Native.Gtk.styleContextAddProviderForDisplay(display, provider, 800);
    }

    private void configureWindowContent(MemorySegment contentWidget) {
        switch (frameType) {
            case TITLED:
                if (isAdwWindow) {
                    // AdwWindow: build Box(AdwHeaderBar + content) and set as content.
                    //   AdwWindow
                    //     └── adw_window_set_content
                    //           └── GtkBox (vertical)
                    //                 ├── AdwHeaderBar
                    //                 └── contentWidget (GtkGraphicsOffload)
                    headerBar = Native.Gtk.adwHeaderBarNew();
                    MemorySegment box = Native.Gtk.boxNew(Native.Gtk.GTK_ORIENTATION_VERTICAL, 0);
                    Native.Gtk.boxAppend(box, headerBar);
                    Native.Gtk.widgetSetVExpand(contentWidget, true);
                    Native.Gtk.boxAppend(box, contentWidget);
                    Native.Gtk.adwWindowSetContent(gtkWindow, box);
                } else {
                    // Plain GtkWindow: add a CSD header bar via titlebar API.
                    headerBar = Native.Gtk.headerBarNew();
                    Native.Gtk.windowSetTitlebar(gtkWindow, headerBar);
                    Native.Gtk.windowSetChild(gtkWindow, contentWidget);
                }
                break;
            case UNTITLED:
                setWindowRootContent(contentWidget);
                break;
            case TRANSPARENT:
                configureTransparentRootContent(contentWidget);
                break;
            case EXTENDED:
                configureExtendedRootOverlay(contentWidget);
                break;
        }
    }

    private void configureTransparentRootContent(MemorySegment contentWidget) {
        // Remove CSD decoration/dropshadow for transparent windows
        Native.Gtk.windowSetDecorated(gtkWindow, false);

        setWindowRootContent(contentWidget);

        String css = "window, window * {"
                + " background-color: transparent;"
                + " background: transparent;"
                + " border-radius: 0;"
                + " border: none;"
                + " box-shadow: none;"
                + " margin: 0;"
                + " padding: 0;"
                + "}";
        MemorySegment provider = Native.Gtk.cssProviderNew();
        Native.Gtk.cssProviderLoadFromString(provider, css);

        // GTK_STYLE_PROVIDER_PRIORITY_APPLICATION = 600
        Native.Gtk.styleContextAddProvider(Native.Gtk.widgetGetStyleContext(gtkWindow), provider, 600);
        Native.Gtk.styleContextAddProvider(Native.Gtk.widgetGetStyleContext(contentWidget), provider, 600);
    }

    // =========================================================================
    // Constructor
    // =========================================================================

    private void configureExtendedRootOverlay(MemorySegment contentWidget) {
        windowRootOverlay = Native.Gtk.overlayNew();
        // contentWidget remains the real scene content; GtkOverlay is just the root container.
        Native.Gtk.overlaySetChild(windowRootOverlay, contentWidget);

        nativeHeaderControlsStart = Native.Gtk.windowControlsNew(Native.Gtk.GTK_PACK_START);
        Native.Gtk.widgetSetHAlign(nativeHeaderControlsStart, Native.Gtk.GTK_ALIGN_START);
        Native.Gtk.widgetSetVAlign(nativeHeaderControlsStart, Native.Gtk.GTK_ALIGN_START);
        Native.Gtk.overlayAddOverlay(windowRootOverlay, nativeHeaderControlsStart);

        nativeHeaderControlsEnd = Native.Gtk.windowControlsNew(Native.Gtk.GTK_PACK_END);
        Native.Gtk.widgetSetHAlign(nativeHeaderControlsEnd, Native.Gtk.GTK_ALIGN_END);
        Native.Gtk.widgetSetVAlign(nativeHeaderControlsEnd, Native.Gtk.GTK_ALIGN_START);
        Native.Gtk.overlayAddOverlay(windowRootOverlay, nativeHeaderControlsEnd);

        applyNativeHeaderControlsPreferences();
        setWindowRootContent(windowRootOverlay);
    }

    // =========================================================================
    // Window content and titlebar configuration
    // =========================================================================

    private boolean usesNativeHeaderControls() {
        return frameType == FrameType.EXTENDED
                && nativeHeaderControlsStart != null
                && nativeHeaderControlsEnd != null
                && !nativeHeaderControlsStart.equals(MemorySegment.NULL)
                && !nativeHeaderControlsEnd.equals(MemorySegment.NULL);
    }

    private void applyNativeHeaderControlsPreferences() {
        if (!usesNativeHeaderControls()) {
            return;
        }

        boolean visible = prefHeaderButtonHeight != 0;
        Native.Gtk.widgetSetVisible(nativeHeaderControlsStart, visible);
        Native.Gtk.widgetSetVisible(nativeHeaderControlsEnd, visible);

        if (visible && prefHeaderButtonHeight > 0) {
            int prefHeight = (int) Math.ceil(prefHeaderButtonHeight);
            Native.Gtk.widgetSetSizeRequest(nativeHeaderControlsStart, -1, prefHeight);
            Native.Gtk.widgetSetSizeRequest(nativeHeaderControlsEnd, -1, prefHeight);
        } else {
            Native.Gtk.widgetSetSizeRequest(nativeHeaderControlsStart, -1, -1);
            Native.Gtk.widgetSetSizeRequest(nativeHeaderControlsEnd, -1, -1);
        }
    }

    void setPrefHeaderButtonHeight(double height) {
        prefHeaderButtonHeight = height;
        applyNativeHeaderControlsPreferences();
        updateNativeHeaderMetrics();
    }

    private void updateNativeHeaderMetrics() {
        if (jfxWindow == null || frameType != FrameType.EXTENDED) {
            return;
        }

        if (!usesNativeHeaderControls() || prefHeaderButtonHeight == 0) {
            setSystemMinimumSize(1, 1);
            jfxWindow.updateNativeHeaderButtonMetrics(0, 0, 0, 0, 0);
            return;
        }

        int startWidth = Native.Gtk.widgetGetWidth(nativeHeaderControlsStart);
        int startHeight = Native.Gtk.widgetGetHeight(nativeHeaderControlsStart);
        int endWidth = Native.Gtk.widgetGetWidth(nativeHeaderControlsEnd);
        int endHeight = Native.Gtk.widgetGetHeight(nativeHeaderControlsEnd);

        boolean startVisible = startWidth > 0 && startHeight > 0;
        boolean endVisible = endWidth > 0 && endHeight > 0;

        int leftWidth = startVisible ? startWidth : 0;
        int leftHeight = startVisible ? startHeight : 0;
        int rightWidth = endVisible ? endWidth : 0;
        int rightHeight = endVisible ? endHeight : 0;
        double measuredMinHeight = Math.max(leftHeight, rightHeight);
        double minHeight = prefHeaderButtonHeight >= 0 ? prefHeaderButtonHeight : measuredMinHeight;

        if (startVisible || endVisible) {
            int minWidth = Math.max(leftWidth + rightWidth, 1);
            int minHeaderHeight = Math.max((int) Math.ceil(Math.max(leftHeight, rightHeight)), 1);
            setSystemMinimumSize(minWidth, minHeaderHeight);
            jfxWindow.updateNativeHeaderButtonMetrics(leftWidth, leftHeight, rightWidth, rightHeight, minHeight);
        } else {
            // Before initial map/layout the control can report 0x0.
            setSystemMinimumSize(1, 1);
            jfxWindow.updateNativeHeaderButtonMetrics(0, 0, 0, 0, minHeight);
        }
    }

    /**
     * Sets the root widget on the window using the appropriate API.
     */
    private void setWindowRootContent(MemorySegment rootWidget) {
        if (isAdwWindow) {
            Native.Gtk.adwWindowSetContent(gtkWindow, rootWidget);
        } else {
            Native.Gtk.windowSetChild(gtkWindow, rootWidget);
        }
    }

    /**
     * Returns {@code true} when this context represents a POPUP backed by a GtkPopover.
     */
    boolean isPopup() {
        return isPopup;
    }

    /**
     * Returns the content widget (GtkGraphicsOffload / DmaBuf area).
     * Used to parent popover children so that pointing-to coordinates
     * are in the content-area coordinate system (below the header bar).
     */
    MemorySegment getChildWidget() {
        return childWidget;
    }

    /**
     * Returns the top-level native widget (GtkWindow for normal windows,
     * GtkPopover for popups).
     */
    private MemorySegment topLevelWidget() {
        return isPopup ? gtkPopover : gtkWindow;
    }

    // =========================================================================
    // Popup helpers
    // =========================================================================

    /**
     * Returns the DMA-BUF compositor for zero-copy presentation via GtkGraphicsOffload.
     */
    @Override
    public Gtk4DmaBufCompositor getCompositor() {
        return compositor;
    }

    private void installEventControllers() {
        // Content widget for event capture
        MemorySegment eventWidget = childWidget;
        MemorySegment toplevel = topLevelWidget();

        // Focus controller — on the toplevel (GtkWindow or GtkPopover, both implement GtkNative)
        MemorySegment focusCtrl = Native.Gtk.eventControllerFocusNew();
        Native.Gtk.widgetAddController(toplevel, focusCtrl);
        connectFocusSignals(focusCtrl);

        // Key controller — on the toplevel so we get keys even when CSD has focus
        MemorySegment keyCtrl = Native.Gtk.eventControllerKeyNew();
        Native.Gtk.widgetAddController(toplevel, keyCtrl);
        connectKeySignals(keyCtrl);

        // Motion controller — on content widget so coordinates are relative to content
        MemorySegment motionCtrl = Native.Gtk.eventControllerMotionNew();
        Native.Gtk.widgetAddController(eventWidget, motionCtrl);
        connectMotionSignals(motionCtrl);

        // Click gesture — on content widget for correct content-area coordinates
        MemorySegment clickGesture = Native.Gtk.gestureClickNew();
        // Accept ALL mouse buttons (not just primary); query actual button in callback
        Native.Gtk.gestureSingleSetButton(clickGesture, 0);
        Native.Gtk.widgetAddController(eventWidget, clickGesture);
        connectClickSignals(clickGesture);

        // Scroll controller — on content widget
        // Flags: GTK_EVENT_CONTROLLER_SCROLL_BOTH_AXES = 3
        MemorySegment scrollCtrl = Native.Gtk.eventControllerScrollNew(3);
        Native.Gtk.widgetAddController(eventWidget, scrollCtrl);
        connectScrollSignals(scrollCtrl);
    }

    private void connectFocusSignals(MemorySegment controller) {
        // "enter" → focus gained
        try {
            MemorySegment enterCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onFocusEnter",
                            MethodType.methodType(void.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(controller, "enter", enterCb);

            MemorySegment leaveCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onFocusLeave",
                            MethodType.methodType(void.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(controller, "leave", leaveCb);
        } catch (NoSuchMethodException | IllegalAccessException e) {
            throw new RuntimeException("Failed to connect focus signals", e);
        }
    }


    // =========================================================================
    // Compositor accessor
    // =========================================================================

    private void connectKeySignals(MemorySegment controller) {
        try {
            // key-pressed: gboolean(GtkEventControllerKey*, guint keyval, guint keycode, GdkModifierType state)
            MemorySegment pressedCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onKeyPressed",
                            MethodType.methodType(int.class,
                                    MemorySegment.class, int.class, int.class, int.class)),
                    FunctionDescriptor.of(ValueLayout.JAVA_INT,
                            ValueLayout.ADDRESS, ValueLayout.JAVA_INT,
                            ValueLayout.JAVA_INT, ValueLayout.JAVA_INT),
                    windowArena);
            Native.GObject.signalConnect(controller, "key-pressed", pressedCb);

            MemorySegment releasedCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onKeyReleased",
                            MethodType.methodType(void.class,
                                    MemorySegment.class, int.class, int.class, int.class)),
                    FunctionDescriptor.ofVoid(
                            ValueLayout.ADDRESS, ValueLayout.JAVA_INT,
                            ValueLayout.JAVA_INT, ValueLayout.JAVA_INT),
                    windowArena);
            Native.GObject.signalConnect(controller, "key-released", releasedCb);
        } catch (NoSuchMethodException | IllegalAccessException e) {
            throw new RuntimeException("Failed to connect key signals", e);
        }
    }

    // =========================================================================
    // Event Controllers (GTK4 model)
    // =========================================================================

