    private void connectWindowSignals() {
        try {
            MemorySegment widget = topLevelWidget();

            if (!isPopup) {
                // ── GtkWindow-specific signals ──────────────────────────

                // "close-request" → gboolean(GtkWindow*, gpointer user_data)
                MemorySegment closeCb = Native.Ffm.upcallStub(
                        MethodHandles.lookup().bind(this, "onCloseRequest",
                                MethodType.methodType(int.class, MemorySegment.class, MemorySegment.class)),
                        FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                        windowArena);
                Native.GObject.signalConnect(gtkWindow, "close-request", closeCb);

                // "notify::maximized" → void(GObject*, GParamSpec*, gpointer user_data)
                MemorySegment maxCb = Native.Ffm.upcallStub(
                        MethodHandles.lookup().bind(this, "onMaximizedChanged",
                                MethodType.methodType(void.class, MemorySegment.class, MemorySegment.class,
                                        MemorySegment.class)),
                        FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                        windowArena);
                Native.GObject.signalConnect(gtkWindow, "notify::maximized", maxCb);

                // "notify::fullscreened" → void(GObject*, GParamSpec*, gpointer user_data)
                MemorySegment fsCb = Native.Ffm.upcallStub(
                        MethodHandles.lookup().bind(this, "onFullscreenChanged",
                                MethodType.methodType(void.class, MemorySegment.class, MemorySegment.class,
                                        MemorySegment.class)),
                        FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                        windowArena);
                Native.GObject.signalConnect(gtkWindow, "notify::fullscreened", fsCb);

                // "notify::scale-factor" → void(GObject*, GParamSpec*, gpointer user_data)
                MemorySegment scaleCb = Native.Ffm.upcallStub(
                        MethodHandles.lookup().bind(this, "onScaleFactorChanged",
                                MethodType.methodType(void.class, MemorySegment.class, MemorySegment.class,
                                        MemorySegment.class)),
                        FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                        windowArena);
                Native.GObject.signalConnect(gtkWindow, "notify::scale-factor", scaleCb);

                // "notify::is-active" → void(GObject*, GParamSpec*, gpointer user_data)
                MemorySegment activeCb = Native.Ffm.upcallStub(
                        MethodHandles.lookup().bind(this, "onActiveChanged",
                                MethodType.methodType(void.class, MemorySegment.class, MemorySegment.class,
                                        MemorySegment.class)),
                        FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                        windowArena);
                Native.GObject.signalConnect(gtkWindow, "notify::is-active", activeCb);
            }

            // ── Common widget signals (GtkWindow and GtkPopover) ────────

            // "realize" → void(GtkWidget*, gpointer user_data)
            MemorySegment realizeCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onRealize",
                            MethodType.methodType(void.class, MemorySegment.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(widget, "realize", realizeCb);

            // "map" → void(GtkWidget*, gpointer user_data)
            MemorySegment mapCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onMap",
                            MethodType.methodType(void.class, MemorySegment.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(widget, "map", mapCb);

            // "unmap" → void(GtkWidget*, gpointer user_data)
            MemorySegment unmapCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onUnmap",
                            MethodType.methodType(void.class, MemorySegment.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(widget, "unmap", unmapCb);

        } catch (NoSuchMethodException | IllegalAccessException e) {
            throw new RuntimeException("Failed to connect window signals", e);
        }
    }

    /**
     * Connects signals on the GdkSurface obtained from the realized GtkWindow.
     * In GTK4, size changes are detected via the {@code GdkSurface::layout} signal
     * instead of the GTK3 {@code GDK_CONFIGURE} event.
     */
    private void connectSurfaceSignals(MemorySegment surface) {
        try {
            // "layout" → void(GdkSurface*, int width, int height, gpointer user_data)
            // This is the GTK4 replacement for GTK3's configure-event / size-allocate.
            // It fires whenever the surface's size changes (e.g., window resize,
            // maximize, fullscreen transitions).
            // GObject always appends user_data; include it for ABI safety.
            MemorySegment layoutCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onSurfaceLayout",
                            MethodType.methodType(void.class,
                                    MemorySegment.class, int.class, int.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS,
                            ValueLayout.JAVA_INT, ValueLayout.JAVA_INT, ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(surface, "layout", layoutCb);

            // "enter-monitor" → void(GdkSurface*, GdkMonitor*, gpointer user_data)
            // Detect when the window moves to a different monitor (e.g., for HiDPI
            // scale changes across monitors).
            MemorySegment enterMonCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onEnterMonitor",
                            MethodType.methodType(void.class,
                                    MemorySegment.class, MemorySegment.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(surface, "enter-monitor", enterMonCb);

            // "leave-monitor" → void(GdkSurface*, GdkMonitor*, gpointer user_data)
            MemorySegment leaveMonCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onLeaveMonitor",
                            MethodType.methodType(void.class,
                                    MemorySegment.class, MemorySegment.class, MemorySegment.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                    windowArena);
            Native.GObject.signalConnect(surface, "leave-monitor", leaveMonCb);

        } catch (NoSuchMethodException | IllegalAccessException e) {
            throw new RuntimeException("Failed to connect surface signals", e);
        }
    }

    /**
     * Extracts the Glass modifier mask from the current event being handled
     * by the given controller. In GTK4, the modifier state (Shift, Ctrl,
     * button masks, etc.) is obtained from the GdkEvent via the controller.
     * This mirrors the GTK3 approach of reading {@code event->state}.
     */
    private int getGlassModifiers(MemorySegment controller) {
        MemorySegment event = Native.Gtk.eventControllerGetCurrentEvent(controller);
        if (event == null || event.equals(MemorySegment.NULL)) {
            return 0;
        }
        int gdkState = Native.Gdk.eventGetModifierState(event);
        return Gtk4KeyMap.toGlassModifier(gdkState);
    }

    /**
     * Computes approximate absolute screen coordinates from view-relative
     * coordinates. On Wayland, the absolute position may not be known,
     * but this is used for popup positioning and drag operations.
     */
    private int toAbsX(int viewRelativeX) {
        // Wayland does not expose global pointer position reliably.
        // Provide best-effort absolute coords from known window origin,
        // otherwise fall back to local coordinates (never constant zero).
        if (windowX >= 0) {
            return windowX + viewRelativeX;
        }
        return viewRelativeX;
    }

    private int toAbsY(int viewRelativeY) {
        if (windowY >= 0) {
            // Account for header bar offset (window → view).
            int topDecoration = Math.max(windowHeight - viewHeight, 0);
            return windowY + topDecoration + viewRelativeY;
        }
        return viewRelativeY;
    }


    // =========================================================================
    // Mouse event helpers
    // =========================================================================

    private void logNotify(String notifyName) {
        System.out.println("[Gtk4WindowContext] " + notifyName);
    }

    private void logNotify(String notifyName, String details) {
        System.out.println("[Gtk4WindowContext] " + notifyName + " " + details);
    }

    @SuppressWarnings("unused")
    void onFocusEnter(MemorySegment controller) {
        // Popup windows are unfocusable — never report focus events.
        if (jfxWindow != null && !isPopup) {
            logNotify("notifyFocusGained");
            jfxWindow.notifyFocusGained();
        }
    }

    @SuppressWarnings("unused")
    void onFocusLeave(MemorySegment controller) {
        // Popup windows are unfocusable — never report focus events.
        if (jfxWindow != null && !isPopup) {
            logNotify("notifyFocusLost");
            jfxWindow.notifyFocusLost();
        }
    }

    @SuppressWarnings("unused")
    int onKeyPressed(MemorySegment controller, int keyval, int keycode, int state) {
        if (jfxWindow != null) {
            logNotify("notifyKeyEvent(pressed)",
                    "keyval=" + keyval + " keycode=" + keycode + " state=" + state);
            jfxWindow.notifyKeyEvent(true, keyval, keycode, state);
        }
        return 0; // FALSE = don't stop propagation
    }

    // =========================================================================
    // Signal callbacks (called from native via upcall stubs)
    // =========================================================================

    @SuppressWarnings("unused")
    void onKeyReleased(MemorySegment controller, int keyval, int keycode, int state) {
        if (jfxWindow != null) {
            logNotify("notifyKeyEvent(released)",
                    "keyval=" + keyval + " keycode=" + keycode + " state=" + state);
            jfxWindow.notifyKeyEvent(false, keyval, keycode, state);
        }
    }

    @SuppressWarnings("unused")
    void onMotion(MemorySegment controller, double x, double y) {
        int ix = (int) x;
        int iy = (int) y;
        lastMouseX = ix;
        lastMouseY = iy;
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(controller);
//            logNotify("notifyMouseMotion",
//                    "x=" + ix + " y=" + iy + " absX=" + toAbsX(ix) + " absY=" + toAbsY(iy)
//                            + " modifiers=" + modifiers);
            jfxWindow.notifyMouseMotion(ix, iy, toAbsX(ix), toAbsY(iy), modifiers);
        }
    }

    @SuppressWarnings("unused")
    void onMouseEnter(MemorySegment controller, double x, double y) {
        mouseEntered = true;
        int ix = (int) x;
        int iy = (int) y;
        lastMouseX = ix;
        lastMouseY = iy;
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(controller);
            logNotify("notifyMouseEnter",
                    "x=" + ix + " y=" + iy + " absX=" + toAbsX(ix) + " absY=" + toAbsY(iy)
                            + " modifiers=" + modifiers);
            jfxWindow.notifyMouseEnter(ix, iy, toAbsX(ix), toAbsY(iy), modifiers);
        }
    }

    @SuppressWarnings("unused")
    void onMouseLeave(MemorySegment controller) {
        mouseEntered = false;
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(controller);
            logNotify("notifyMouseExit",
                    "x=" + lastMouseX + " y=" + lastMouseY
                            + " absX=" + toAbsX(lastMouseX) + " absY=" + toAbsY(lastMouseY)
                            + " modifiers=" + modifiers);
            jfxWindow.notifyMouseExit(lastMouseX, lastMouseY,
                    toAbsX(lastMouseX), toAbsY(lastMouseY), modifiers);
        }
    }

    @SuppressWarnings("unused")
    void onClickPressed(MemorySegment gesture, int nPress, double x, double y) {
        if (jfxWindow != null) {
            int gdkButton = Native.Gtk.gestureSingleGetCurrentButton(gesture);
            int ix = (int) x;
            int iy = (int) y;
            lastMouseX = ix;
            lastMouseY = iy;

            if (beginNativeWindowMove(gesture, gdkButton, ix, iy)) {
                return;
            }

            int modifiers = getGlassModifiers(gesture);
            logNotify("notifyMouseButton(pressed)",
                    "button=" + gdkButton + " nPress=" + nPress
                            + " x=" + ix + " y=" + iy
                            + " absX=" + toAbsX(ix) + " absY=" + toAbsY(iy)
                            + " modifiers=" + modifiers);
            jfxWindow.notifyMouseButton(true, gdkButton, ix, iy,
                    toAbsX(ix), toAbsY(iy), modifiers);
        }
    }

    @SuppressWarnings("unused")
    void onClickReleased(MemorySegment gesture, int nPress, double x, double y) {
        if (jfxWindow != null) {
            int gdkButton = Native.Gtk.gestureSingleGetCurrentButton(gesture);

            if (suppressClickRelease && gdkButton == 1) {
                suppressClickRelease = false;
                return;
            }

            int ix = (int) x;
            int iy = (int) y;
            lastMouseX = ix;
            lastMouseY = iy;
            int modifiers = getGlassModifiers(gesture);
            logNotify("notifyMouseButton(released)",
                    "button=" + gdkButton + " nPress=" + nPress
                            + " x=" + ix + " y=" + iy
                            + " absX=" + toAbsX(ix) + " absY=" + toAbsY(iy)
                            + " modifiers=" + modifiers);
            jfxWindow.notifyMouseButton(false, gdkButton, ix, iy,
                    toAbsX(ix), toAbsY(iy), modifiers);
        }
    }

    @SuppressWarnings("unused")
    int onScroll(MemorySegment controller, double dx, double dy) {
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(controller);
            logNotify("notifyScroll",
                    "x=" + lastMouseX + " y=" + lastMouseY
                            + " absX=" + toAbsX(lastMouseX) + " absY=" + toAbsY(lastMouseY)
                            + " dx=" + dx + " dy=" + dy + " modifiers=" + modifiers);
            jfxWindow.notifyScroll(lastMouseX, lastMouseY,
                    toAbsX(lastMouseX), toAbsY(lastMouseY),
                    dx, dy, modifiers);
        }
        return 0;
    }

    @SuppressWarnings("unused")
    int onCloseRequest(MemorySegment window, MemorySegment userData) {
        if (jfxWindow != null) {
            logNotify("notifyCloseRequest");
            jfxWindow.notifyCloseRequest();
        }
        return 1; // TRUE = we handled it, don't destroy
    }

    @SuppressWarnings("unused")
    void onMaximizedChanged(MemorySegment object, MemorySegment pspec, MemorySegment userData) {
        if (jfxWindow != null) {
            if (Native.Gtk.windowIsMaximized(gtkWindow)) {
                logNotify("notifyStateMaximized");
                jfxWindow.notifyStateMaximized();
            } else {
                logNotify("notifyStateRestored");
                jfxWindow.notifyStateRestored();
            }
        }
    }

    @SuppressWarnings("unused")
    void onFullscreenChanged(MemorySegment object, MemorySegment pspec, MemorySegment userData) {
        if (jfxWindow != null) {
            if (Native.Gtk.windowIsFullscreen(gtkWindow)) {
                logNotify("notifyFullscreenEnter");
                jfxWindow.notifyFullscreenEnter();
            } else {
                logNotify("notifyFullscreenExit");
                jfxWindow.notifyFullscreenExit();
            }
        }
    }

    @SuppressWarnings("unused")
    void onRealize(MemorySegment widget, MemorySegment userData) {
        // The GdkSurface is now available. Store it and connect surface-level signals.
        // Both GtkWindow and GtkPopover implement GtkNative → have a GdkSurface.
        gdkSurface = Native.Gdk.nativeGetSurface(topLevelWidget());
        if (gdkSurface != null && !gdkSurface.equals(MemorySegment.NULL)) {
            connectSurfaceSignals(gdkSurface);
        }

        updateNativeHeaderMetrics();
    }

    @SuppressWarnings("unused")
    void onMap(MemorySegment widget, MemorySegment userData) {
        // Window has become visible on screen.
        mapped = true;
        updateWindowSize();
        updateNativeHeaderMetrics();
        notifyWindowSize();
        notifyViewResize();
        notifyRepaint();
    }

    @SuppressWarnings("unused")
    void onUnmap(MemorySegment widget, MemorySegment userData) {
        // Window has been hidden.
        mapped = false;
        if (mouseEntered && jfxWindow != null) {
            mouseEntered = false;
            logNotify("notifyMouseExit",
                    "x=" + lastMouseX + " y=" + lastMouseY
                            + " absX=" + toAbsX(lastMouseX) + " absY=" + toAbsY(lastMouseY)
                            + " modifiers=0");
            jfxWindow.notifyMouseExit(lastMouseX, lastMouseY,
                    toAbsX(lastMouseX), toAbsY(lastMouseY), 0);
        }
    }

    /**
     * Called when the GdkSurface layout changes (the GTK4 equivalent of
     * GTK3's {@code GDK_CONFIGURE} event / {@code process_configure()}).
     * <p>
     * The width/height parameters are in application (logical) pixels.
     */
    @SuppressWarnings("unused")
    void onSurfaceLayout(MemorySegment surface, int surfaceWidth, int surfaceHeight, MemorySegment userData) {
        int oldWindowWidth = windowWidth;
        int oldWindowHeight = windowHeight;
        int oldViewWidth = viewWidth;
        int oldViewHeight = viewHeight;


        updateWindowSize();
        updateNativeHeaderMetrics();

        boolean windowSizeChanged = (oldWindowWidth != windowWidth || oldWindowHeight != windowHeight);
        boolean viewSizeChanged = (oldViewWidth != viewWidth || oldViewHeight != viewHeight);

        if (windowSizeChanged || viewSizeChanged) {
            // Notify window resize first (updates Glass Window width/height).
            notifyWindowSize();
            // Always notify view resize together with window resize, matching
            // the GTK3 behavior where process_configure() calls both
            // jWindowNotifyResize and jViewNotifyResize atomically.
            notifyViewResize();
            // Trigger a repaint so Prism re-renders at the new dimensions.
            notifyRepaint();
        }
    }

    /**
     * Called when the window's surface enters a new monitor.
     * Used to detect HiDPI scale changes when dragging between monitors.
     */
    @SuppressWarnings("unused")
    void onEnterMonitor(MemorySegment surface, MemorySegment monitor, MemorySegment userData) {
        int newScale = Native.Gtk.widgetGetScaleFactor(topLevelWidget());
        if (jfxWindow != null && newScale > 0) {
            float scale = (float) newScale;
            logNotify("notifyScaleFactorChanged", "sx=1.0 sy=1.0 px=" + scale + " py=" + scale);
            jfxWindow.notifyScaleFactorChanged(1.0f, 1.0f, scale, scale);
        }
    }

    /**
     * Called when the window's surface leaves a monitor.
     */
    @SuppressWarnings("unused")
    void onLeaveMonitor(MemorySegment surface, MemorySegment monitor, MemorySegment userData) {
    }

    /**
     * Called when the {@code GtkWindow:is-active} property changes.
     * This tracks whether this window is the active (focused) toplevel,
     * complementing the {@code GtkEventControllerFocus} enter/leave signals
     * which track keyboard focus on a specific widget.
     */
    @SuppressWarnings("unused")
    void onActiveChanged(MemorySegment object, MemorySegment pspec, MemorySegment userData) {
        // Popup windows are unfocusable — never report activation changes.
        if (jfxWindow != null && !isPopup) {
            boolean active = Native.Gtk.windowIsActive(gtkWindow);
            if (active) {
                logNotify("notifyFocusGained");
                jfxWindow.notifyFocusGained();
            } else {
                logNotify("notifyFocusLost");
                jfxWindow.notifyFocusLost();
            }
        }
    }

    @SuppressWarnings("unused")
    void onSizeChanged(MemorySegment object, MemorySegment pspec) {
        int oldWindowWidth = windowWidth;
        int oldWindowHeight = windowHeight;
        int oldViewWidth = viewWidth;
        int oldViewHeight = viewHeight;

        updateWindowSize();
        updateNativeHeaderMetrics();

        boolean windowSizeChanged = (oldWindowWidth != windowWidth || oldWindowHeight != windowHeight);
        boolean viewSizeChanged = (oldViewWidth != viewWidth || oldViewHeight != viewHeight);

        if (windowSizeChanged || viewSizeChanged) {
            // Notify window resize first (updates Glass Window width/height).
            notifyWindowSize();
            // Always notify view resize together with window resize, matching
            // the GTK3 behavior where process_configure() calls both
            // jWindowNotifyResize and jViewNotifyResize atomically.
            notifyViewResize();
            // Trigger a repaint so Prism re-renders at the new dimensions.
            notifyRepaint();
        }
    }

    @SuppressWarnings("unused")
    void onScaleFactorChanged(MemorySegment object, MemorySegment pspec, MemorySegment userData) {
        int newScale = Native.Gtk.widgetGetScaleFactor(topLevelWidget());
        if (jfxWindow != null && newScale > 0) {
            float scale = (float) newScale;
            // GTK4 reports logical coordinates; keep platform scale at 1.0.
            logNotify("notifyScaleFactorChanged", "sx=1.0 sy=1.0 px=" + scale + " py=" + scale);
            jfxWindow.notifyScaleFactorChanged(1.0f, 1.0f, scale, scale);
        }
    }

    MemorySegment getGtkWindow() {
        return gtkWindow;
    }

    /**
     * Returns the GdkSurface* for this window, or null if not yet realized.
     */
    @Override
    public MemorySegment getGdkSurface() {
        return gdkSurface;
    }

    /**
     * Returns the native surface handle for EGL rendering.
     * Always returns 0 because all windows use the DMA-BUF compositor path:
     * Prism renders to an offscreen FBO and publishes the texture via
     * {@code publishRenderedTexture} → {@code publishFrame}.
     */
    @Override
    public long getNativeSurfaceHandle() {
        // Compositor path: no native window, Prism uses pbuffer + FBO
        return 0;
    }

    // =========================================================================
    // Window operations (called from Gtk4Window)
    // =========================================================================

    @Override
    public boolean isVisible() {
        return visible;
    }

    @Override
    public void setVisible(boolean visible) {
        System.out.println("[Gtk4WindowContext] setVisible: visible=" + visible
                + " frameType=" + frameType + " windowType=" + windowType
                + " isPopup=" + isPopup + " mapped=" + mapped + " destroyed=" + destroyed);
        this.visible = visible;

        if (visible) {
            if (isPopup) {
                // ── Popup path (GtkPopover) ────────────────────────────
                Native.Gtk.popoverPopup(gtkPopover);
                mapped = true;

                int scaleFactor = Native.Gtk.widgetGetScaleFactor(gtkPopover);
                if (scaleFactor > 0 && jfxWindow != null) {
                    float scale = (float) scaleFactor;
                    logNotify("notifyScaleFactorChanged", "sx=1.0 sy=1.0 px=" + scale + " py=" + scale);
                    jfxWindow.notifyScaleFactorChanged(1.0f, 1.0f, scale, scale);
                }

                updateWindowSize();
                notifyWindowMove();
                notifyWindowSize();
                notifyViewResize();
                notifyRepaint();
            } else {
                // ── Normal / utility / transparent window path ─────────
                Native.Gtk.widgetSetVisible(gtkWindow, true);
                Native.Gtk.windowPresent(gtkWindow);
                mapped = true;

                int scaleFactor = Native.Gtk.widgetGetScaleFactor(gtkWindow);
                if (scaleFactor > 0 && jfxWindow != null) {
                    float scale = (float) scaleFactor;
                    logNotify("notifyScaleFactorChanged", "sx=1.0 sy=1.0 px=" + scale + " py=" + scale);
                    jfxWindow.notifyScaleFactorChanged(1.0f, 1.0f, scale, scale);
                }

                updateWindowSize();
                notifyWindowSize();
                notifyViewResize();
                notifyRepaint();

                if (jfxWindow != null && !disabled) {
                    logNotify("notifyFocusGained");
                    jfxWindow.notifyFocusGained();
                }
            }
        } else {
            if (isPopup) {
                Native.Gtk.popoverPopdown(gtkPopover);
            } else {
                Native.Gtk.widgetSetVisible(gtkWindow, false);
            }
            mapped = false;
            if (mouseEntered && jfxWindow != null) {
                mouseEntered = false;
                logNotify("notifyMouseExit",
                        "x=" + lastMouseX + " y=" + lastMouseY
                                + " absX=" + toAbsX(lastMouseX) + " absY=" + toAbsY(lastMouseY)
                                + " modifiers=0");
                jfxWindow.notifyMouseExit(lastMouseX, lastMouseY,
                        toAbsX(lastMouseX), toAbsY(lastMouseY), 0);
            }
        }
    }

    @Override
    public void setTitle(String title) {
        if (isPopup) {
            return;
        }
        Native.Gtk.windowSetTitle(gtkWindow, title != null ? title : "");
    }

    boolean isResizable() {
        return resizable;
    }

    @Override
    public void setResizable(boolean resizable) {
        this.resizable = resizable;
        if (!isPopup) {
            Native.Gtk.windowSetResizable(gtkWindow, resizable);
        }
    }

    @Override
    public void setAlpha(float alpha) {
        Native.Gtk.widgetSetOpacity(topLevelWidget(), alpha);
    }

    @Override
    public void setEnabled(boolean enabled) {
        this.disabled = !enabled;
        Native.Gtk.widgetSetSensitive(topLevelWidget(), enabled);
    }

    @Override
    public void setBackground(float r, float g, float b) {
        // In GTK4, background color is set via CSS
        String css = String.format("window { background-color: rgb(%d,%d,%d); }",
                (int) (r * 255), (int) (g * 255), (int) (b * 255));
        MemorySegment provider = Native.Gtk.cssProviderNew();
        Native.Gtk.cssProviderLoadFromString(provider, css);
        MemorySegment styleCtx = Native.Gtk.widgetGetStyleContext(topLevelWidget());
        // GTK_STYLE_PROVIDER_PRIORITY_APPLICATION = 600
        Native.Gtk.styleContextAddProvider(styleCtx, provider, 600);
    }

    @Override
    public void setMinimumSize(int w, int h) {
        this.minWidth = w;
        this.minHeight = h;
        updateSizeConstraints();
    }

    void setSystemMinimumSize(int w, int h) {
        this.sysMinWidth = w;
        this.sysMinHeight = h;
        updateSizeConstraints();
    }

    @Override
    public void setMaximumSize(int w, int h) {
        this.maxWidth = (w == -1) ? Integer.MAX_VALUE : w;
        this.maxHeight = (h == -1) ? Integer.MAX_VALUE : h;
        updateSizeConstraints();
    }

    private void updateSizeConstraints() {
        MemorySegment widget = topLevelWidget();
        if (!resizable && !disabled) {
            // Fixed size: set size request to current view size
            Native.Gtk.widgetSetSizeRequest(widget,
                    Math.max(viewWidth, 1), Math.max(viewHeight, 1));
        } else {
            int effectiveMinW = Math.max(minWidth, sysMinWidth);
            int effectiveMinH = Math.max(minHeight, sysMinHeight);
            Native.Gtk.widgetSetSizeRequest(widget,
                    Math.max(effectiveMinW, 1),
                    Math.max(effectiveMinH, 1));
        }
    }

    @Override
    public void setMinimized(boolean minimize) {
        if (isPopup) {
            return;
        }
        if (mapped) {
            if (minimize) {
                Native.Gtk.windowMinimize(gtkWindow);
            } else {
                Native.Gtk.windowUnminimize(gtkWindow);
            }
        }
    }

    boolean isMaximized() {
        if (isPopup) {
            return false;
        }
        return Native.Gtk.windowIsMaximized(gtkWindow);
    }

    @Override
    public void setMaximized(boolean maximize) {
        if (isPopup) {
            return;
        }
        if (mapped) {
            if (maximize) {
                Native.Gtk.windowMaximize(gtkWindow);
            } else {
                Native.Gtk.windowUnmaximize(gtkWindow);
            }
        }
    }

    boolean isFullscreen() {
        if (isPopup) {
            return false;
        }
        return Native.Gtk.windowIsFullscreen(gtkWindow);
    }

    boolean isFloating() {
        return !isMaximized() && !isFullscreen();
    }

    void enterFullscreen() {
        if (isPopup) {
            return;
        }
        Native.Gtk.windowFullscreen(gtkWindow);
    }

    void exitFullscreen() {
        if (isPopup) {
            return;
        }
        Native.Gtk.windowUnfullscreen(gtkWindow);
    }

    @Override
    public void requestFocus() {
        if (!visible || isPopup) {
            return;
        }
        Native.Gtk.windowPresent(gtkWindow);
    }

    @Override
    public void setFocusable(boolean focusable) {
        this.focusable = focusable;
        if (!isPopup) {
            // Propagate to GTK4: unfocusable windows must not
            // steal keyboard focus or activation from the owner.
            Native.Gtk.widgetSetFocusable(gtkWindow, focusable);
        }
    }

    @Override
    public void setCursor(String cursorName) {
        MemorySegment widget = topLevelWidget();
        if (cursorName != null) {
            MemorySegment cursor = Native.Gdk.cursorNewFromName(cursorName);
            Native.Gtk.widgetSetCursor(widget, cursor);
        } else {
            Native.Gtk.widgetSetCursor(widget, MemorySegment.NULL);
        }
    }

    @Override
    public void toFront() {
        if (isPopup) {
            return;
        }
        Native.Gtk.windowPresent(gtkWindow);
    }

    @Override
    public void toBack() {
        if (isPopup) {
            return;
        }
        // GTK4 has no direct "lower" API. The window will stay in its stacking order.
        // For X11, an X11-specific call would be needed. This is a known limitation.
    }

    void setModal(boolean modal, Gtk4WindowContext parent) {
        if (isPopup) {
            return;
        }
        if (modal && parent != null) {
            Native.Gtk.windowSetTransientFor(gtkWindow, parent.gtkWindow);
        }
        Native.Gtk.windowSetModal(gtkWindow, modal);
    }

    @Override
    public void setLevel(int level) {
        // Level NORMAL = 0, FLOATING = 1, TOPMOST = 2
        // GTK4 doesn't have a direct keep-above API like GTK3.
        // This is tracked internally for child window propagation.
        onTop = (level != 0);
        updateOntopTree(onTop);
    }

    private void updateOntopTree(boolean effective) {
        // GTK4 doesn't have gdk_window_set_keep_above.
        // For X11, this would require Xlib calls via FFI.
        // We track the state for child propagation.
        for (Gtk4WindowContext child : children) {
            child.updateOntopTree(effective || child.onTop);
        }
    }

    boolean effectiveOnTop() {
        if (owner != null) {
            return owner.effectiveOnTop() || onTop;
        }
        return onTop;
    }

    @Override
    public void setIcon(int width, int height, int[] pixels) {
        // In GTK4, window icons are set via a GdkPaintable (GdkTexture)
        // This requires creating a GdkMemoryTexture from pixel data
        if (pixels == null || width <= 0 || height <= 0) {
            return;
        }

        try (Arena arena = Arena.ofConfined()) {
            // ARGB32 pixels → copy to native memory
            long dataSize = (long) width * height * 4;
            MemorySegment nativeData = arena.allocate(dataSize);
            for (int i = 0; i < width * height; i++) {
                nativeData.setAtIndex(ValueLayout.JAVA_INT, i, pixels[i]);
            }

            MemorySegment gbytes = Native.Glib.bytesNew(nativeData, dataSize);
            // GDK_MEMORY_B8G8R8A8_PREMULTIPLIED = 0 (approximately; depends on endianness)
            MemorySegment texture = Native.Gdk.memoryTextureNew(width, height, 0, gbytes, (long) width * 4);
            Native.Glib.bytesUnref(gbytes);

            // GTK4: gtk_window_set_icon_name is the primary API but doesn't accept paintable directly.
            // For custom pixel icons, we'd need to register a named icon or use a different approach.
            // This is a simplified implementation.
        }
    }

    @Override
    public void setBounds(int x, int y, boolean xSet, boolean ySet,
                          int w, int h, int cw, int ch,
                          float gravityX, float gravityY) {
        System.out.println("[Gtk4WindowContext] setBounds: x=" + x + " y=" + y
                + " xSet=" + xSet + " ySet=" + ySet
                + " w=" + w + " h=" + h + " cw=" + cw + " ch=" + ch
                + " frameType=" + frameType + " windowType=" + windowType
                + " mapped=" + mapped + " visible=" + visible);
        int oldViewWidth = viewWidth;
        int oldViewHeight = viewHeight;
        int oldWindowWidth = windowWidth;
        int oldWindowHeight = windowHeight;
        this.gravityX = gravityX;
        this.gravityY = gravityY;

        // Current decoration insets: difference between window and view (header bar).
        // For UNTITLED/TRANSPARENT/POPUP: extW=0, extH=0
        // For TITLED with header bar: extW=0, extH=headerBarHeight
        int extW = Math.max(windowWidth - viewWidth, 0);
        int extH = Math.max(windowHeight - viewHeight, 0);


        int requestedWindowW = 0, requestedWindowH = 0;
        int requestedViewW = 0, requestedViewH = 0;

        if (w > 0) {
            // w/h = total window size (including header bar)
            widthType = BoundsType.WINDOW;
            requestedWindowW = Math.clamp(w, 1, MAX_WINDOW_SIZE);
            requestedViewW = Math.clamp(w - extW, 1, MAX_WINDOW_SIZE);
        } else if (cw > 0) {
            // cw/ch = content/view size → add ext to get window size
            if (widthType == BoundsType.UNKNOWN) {
                widthType = BoundsType.VIEW;
            }
            requestedViewW = Math.clamp(cw, 1, MAX_WINDOW_SIZE);
            requestedWindowW = Math.clamp(cw + extW, 1, MAX_WINDOW_SIZE);
        }

        if (h > 0) {
            heightType = BoundsType.WINDOW;
            requestedWindowH = Math.clamp(h, 1, MAX_WINDOW_SIZE);
            requestedViewH = Math.clamp(h - extH, 1, MAX_WINDOW_SIZE);
        } else if (ch > 0) {
            if (heightType == BoundsType.UNKNOWN) {
                heightType = BoundsType.VIEW;
            }
            requestedViewH = Math.clamp(ch, 1, MAX_WINDOW_SIZE);
            requestedWindowH = Math.clamp(ch + extH, 1, MAX_WINDOW_SIZE);
        }

        // ── GtkWindow path (all window types) ──
        if (mapped && !isFloating()) {
            // Ignore when maximized/fullscreen
            notifyWindowSize();
            notifyViewResize();
            notifyWindowMove();
            notifyRepaint();
            return;
        }

        int finalWindowW = (requestedWindowW > 0) ? requestedWindowW : Math.max(windowWidth, 1);
        int finalWindowH = (requestedWindowH > 0) ? requestedWindowH : Math.max(windowHeight, 1);
        int finalViewW = (requestedViewW > 0) ? requestedViewW : Math.max(viewWidth, 1);
        int finalViewH = (requestedViewH > 0) ? requestedViewH : Math.max(viewHeight, 1);
        int finalX = xSet ? x : windowX;
        int finalY = ySet ? y : windowY;

        // Apply constraints (constraints are in window coordinates)
        int effectiveMinW = Math.max(minWidth, sysMinWidth);
        int effectiveMinH = Math.max(minHeight, sysMinHeight);

        if (effectiveMinW > 0 && finalWindowW < effectiveMinW) {
            finalWindowW = effectiveMinW;
        }
        if (maxWidth > 0 && finalWindowW > maxWidth) {
            finalWindowW = maxWidth;
        }
        if (effectiveMinH > 0 && finalWindowH < effectiveMinH) {
            finalWindowH = effectiveMinH;
        }
        if (maxHeight > 0 && finalWindowH > maxHeight) {
            finalWindowH = maxHeight;
        }

        finalWindowW = Math.clamp(finalWindowW, 1, MAX_WINDOW_SIZE);
        finalWindowH = Math.clamp(finalWindowH, 1, MAX_WINDOW_SIZE);

        windowX = finalX;
        windowY = finalY;

        if (isPopup) {
            // ── Popup path: position via popoverSetPointingTo, size via widgetSetSizeRequest ──
            // Convert absolute JavaFX coordinates to owner-window-relative.
            // The popover is parented to the owner's GtkWindow, so pointing-to
            // coordinates are in the GtkWindow's coordinate space (which in
            // GTK4 CSD includes the title bar area at the top).
            int relX = finalX;
            int relY = finalY;
            if (owner != null) {
                relX = finalX - owner.windowX;
                relY = finalY - owner.windowY;
            }
            // GtkPopover with GTK_POS_BOTTOM places itself below the pointing-to
            // rectangle, centered horizontally.  We set the rectangle width to the
            // popup width so the centering puts the left edge at relX, and height=0
            // so the top edge lands exactly at relY.
            Native.Gtk.popoverSetPointingTo(gtkPopover, relX, relY, finalWindowW, 0);
            Native.Gtk.widgetSetSizeRequest(childWidget, finalWindowW, finalWindowH);

            updateWindowSize();
            if (Native.Gtk.widgetGetWidth(gtkPopover) <= 0) {
                windowWidth = finalWindowW;
                windowHeight = finalWindowH;
                viewWidth = finalViewW;
                viewHeight = finalViewH;
            }
        } else {
            // ── GtkWindow path ──────────────────────────────────────────
            Native.Gtk.windowSetDefaultSize(gtkWindow, finalWindowW, finalWindowH);

            // Try to read actual sizes from GTK; if not yet realized (returns 0),
            // use the requested sizes so Prism renders at the correct dimensions
            // from the first frame. onSizeChanged will correct with actual GTK
            // values once the window is shown.
            updateWindowSize();
            if (Native.Gtk.widgetGetWidth(gtkWindow) <= 0) {
                // Window not yet shown — use requested sizes as best estimate.
                windowWidth = finalWindowW;
                windowHeight = finalWindowH;
                viewWidth = finalViewW;
                viewHeight = finalViewH;
            }
        }

        // Notify Glass of size changes — always notify both window and view
        // together, then trigger a repaint (matching GTK3 behavior).
        boolean sizeChanged = (oldWindowWidth != windowWidth || oldWindowHeight != windowHeight
                || oldViewWidth != viewWidth || oldViewHeight != viewHeight);
        boolean positionChanged = (xSet || ySet);
        if (sizeChanged || positionChanged) {
            // Always notify position: on Wayland, we cannot physically move a
            // GdkToplevel, but JavaFX needs the intended coordinates for
            // absolute position calculations (toAbsX/toAbsY) and for popup
            // anchor positioning.
            notifyWindowMove();
            if (sizeChanged) {
                notifyWindowSize();
                notifyViewResize();
            }
            notifyRepaint();
        }
    }

    private void updateWindowSize() {
        MemorySegment toplevel = topLevelWidget();
        int gtkWindowW = Native.Gtk.widgetGetWidth(toplevel);
        int gtkWindowH = Native.Gtk.widgetGetHeight(toplevel);
        int gtkViewW = Native.Gtk.widgetGetWidth(childWidget);
        int gtkViewH = Native.Gtk.widgetGetHeight(childWidget);

        // Window = total GtkWindow/AdwWindow/GtkPopover size (includes header bar for titled windows)
        if (gtkWindowW > 0) {
            windowWidth = Math.clamp(gtkWindowW, 1, MAX_WINDOW_SIZE);
        }
        if (gtkWindowH > 0) {
            windowHeight = Math.clamp(gtkWindowH, 1, MAX_WINDOW_SIZE);
        }
        // View = child widget size (DmaBuf content area, excludes header bar)
        if (gtkViewW > 0) {
            viewWidth = Math.clamp(gtkViewW, 1, MAX_WINDOW_SIZE);
        }
        if (gtkViewH > 0) {
            viewHeight = Math.clamp(gtkViewH, 1, MAX_WINDOW_SIZE);
        }
    }

    void addChild(Gtk4WindowContext child) {
        children.add(child);
    }

    void removeChild(Gtk4WindowContext child) {
        children.remove(child);
    }

    void setOwner(Gtk4WindowContext newOwner) {
        this.owner = newOwner;
    }

    // =========================================================================
    // Child management
    // =========================================================================

    private void notifyWindowSize() {
        if (jfxWindow != null) {
            logNotify("notifyResizeEvent", "width=" + windowWidth + " height=" + windowHeight);
            jfxWindow.notifyResizeEvent(windowWidth, windowHeight);
        }
    }

    private void notifyViewResize() {
        if (jfxWindow != null) {
            logNotify("notifyViewResize", "width=" + viewWidth + " height=" + viewHeight);
            jfxWindow.notifyViewResize(viewWidth, viewHeight);
        }
    }

    private void notifyWindowMove() {
        if (jfxWindow != null) {
            logNotify("notifyMoveEvent", "x=" + windowX + " y=" + windowY);
            jfxWindow.notifyMoveEvent(windowX, windowY);
        }
    }

    // =========================================================================
    // Notifications to Java Glass layer
    // =========================================================================

    /**
     * Triggers a repaint notification on the current view so that Prism
     * schedules a render pulse and re-renders the scene at the current
     * dimensions.  This mirrors what the Monocle backend does in
     * {@code MonocleWindow.notifyResizeAndMove()}.
     */
    private void notifyRepaint() {
        if (jfxWindow != null) {
            logNotify("notifyViewRepaint");
            jfxWindow.notifyViewRepaint();
        }
    }

    private boolean beginNativeWindowMove(MemorySegment gesture, int gdkButton, int x, int y) {
        if (frameType != FrameType.EXTENDED || gdkButton != 1 || !isFloating() || jfxWindow == null) {
            return false;
        }

        // Event-controller coordinates are view-local logical values.
        // nonClientHitTest expects view-local physical coordinates.
        int localPhysicalX = (int) Math.round(x * jfxWindow.getPlatformScaleX());
        int localPhysicalY = (int) Math.round(y * jfxWindow.getPlatformScaleY());
        if (jfxWindow.nonClientHitTest(localPhysicalX, localPhysicalY) != HT_CAPTION) {
            return false;
        }

        if (gdkSurface == null || gdkSurface.equals(MemorySegment.NULL)) {
            return false;
        }

        MemorySegment event = Native.Gtk.eventControllerGetCurrentEvent(gesture);
        if (event == null || event.equals(MemorySegment.NULL)) {
            return false;
        }

        MemorySegment device = Native.Gdk.eventGetDevice(event);
        if (device == null || device.equals(MemorySegment.NULL)) {
            return false;
        }

        // Pass surface-local coordinates from the press event.
        Native.Gdk.toplevelBeginMove(gdkSurface, device, gdkButton,
                x, y, Native.Gdk.eventGetTime(event));
        suppressClickRelease = true;
        return true;
    }

    @Override
    public void updateViewSize() {
        notifyViewResize();
        notifyRepaint();
    }

    @Override
    public int getViewWidth() {
        return viewWidth;
    }

    @Override
    public int getViewHeight() {
        return viewHeight;
    }


    // =========================================================================
    // View management
    // =========================================================================

    int getViewX() {
        return viewX;
    }

    int getViewY() {
        return viewY;
    }

    @Override
    public void destroy() {
        System.out.println("[Gtk4WindowContext] destroy: frameType=" + frameType
                + " windowType=" + windowType + " isPopup=" + isPopup
                + " destroyed=" + destroyed + " visible=" + visible + " mapped=" + mapped
                + " children=" + children.size());
        if (destroyed) {
            return;
        }
        destroyed = true;

        // Clear surface reference (signals are cleaned up when windowArena closes)
        gdkSurface = null;

        // Clean up DMA-BUF compositor resources before destroying the window
        if (compositor != null) {
            compositor.dispose();
        }

        if (owner != null) {
            owner.removeChild(this);
        }

        for (Gtk4WindowContext child : new HashSet<>(children)) {
            child.setOwner(null);
            child.destroy();
        }
        children.clear();

        if (jfxWindow != null) {
            logNotify("notifyDestroyEvent");
            jfxWindow.notifyDestroyEvent();
        }

        if (isPopup) {
            // GtkPopover is destroyed by unparenting it.
            Native.Gtk.widgetUnparent(gtkPopover);
        } else {
            Native.Gtk.windowDestroy(gtkWindow);
        }
        windowArena.close();
    }

    enum FrameType {TITLED, UNTITLED, TRANSPARENT, EXTENDED}

    enum WindowType {NORMAL, UTILITY, POPUP}

    // =========================================================================
    // Destroy
    // =========================================================================

    private enum BoundsType {UNKNOWN, VIEW, WINDOW}
}

