                    MethodHandles.lookup().bind(this, "onMotion",
                            MethodType.methodType(void.class,
                                    MemorySegment.class, double.class, double.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS,
                            ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE),
                    windowArena);
            Native.GObject.signalConnect(controller, "motion", motionCb);

            // enter: void(GtkEventControllerMotion*, double x, double y)
            MemorySegment enterCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onMouseEnter",
                            MethodType.methodType(void.class,
                                    MemorySegment.class, double.class, double.class)),
                    FunctionDescriptor.ofVoid(ValueLayout.ADDRESS,
                            ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE),
                    windowArena);
            Native.GObject.signalConnect(controller, "enter", enterCb);

            // leave: void(GtkEventControllerMotion*)
            MemorySegment leaveCb = Native.Ffm.upcallStub(
                    MethodHandles.lookup().bind(this, "onMouseLeave",
                            MethodType.methodType(void.class, MemorySegment.class)),
