final class Gtk4WindowHandler {

    static final int DEFAULT_WIDTH = 320;
    static final int DEFAULT_HEIGHT = 200;
    static final int MAX_WINDOW_SIZE = 32767;
    private static final MethodHandles.Lookup LOOKUP = MethodHandles.lookup();
    private static final double USE_DEFAULT_HEADER_BUTTON_SIZE = -1;
    private static final int HT_CAPTION = 1;

    private static boolean popupCssRegistered;
    private static boolean transparentCssRegistered;

    private static Gtk4WindowHandler grabWindow;
    private final Gtk4Window jfxWindow;

    private final GtkWindow gtkWindow;
    private final GtkPopover gtkPopover;
    private final Arena windowArena;
    private final boolean isAdwWindow;
    private final boolean isPopup;
    private final Gtk4Compositor compositor;
    private final GtkWidget childWidget;
    private final Set<Gtk4WindowHandler> children = new HashSet<>();
    private final FrameType frameType;
    private final WindowType windowType;
    private final ObservableSize windowSize;
    private final ObservableSize viewSize;
    private GtkHeaderBar headerBar;
    private GtkOverlay windowRootOverlay;
    private GtkWidget nativeHeaderControlsStart;
    private GtkWidget nativeHeaderControlsEnd;
    private GdkToplevel gdkToplevel;
    private Gtk4WindowHandler owner;
    private boolean visible;
    private boolean mapped;
    private boolean destroyed;
    private static final int INITIAL_STATE_MAXIMIZED  = 1;
    private static final int INITIAL_STATE_FULLSCREEN = 1 << 1;
    private static final int INITIAL_STATE_ICONIFIED  = 1 << 2;
    private int initialState = 0;
    private boolean disabled;
    private boolean resizable = true;
    private boolean mouseEntered;
    private boolean sizeAssigned;
    private int viewX;
    private int viewY;
    private int minWidth = 1, minHeight = 1;
    private int maxWidth = Integer.MAX_VALUE, maxHeight = Integer.MAX_VALUE;
    private int sysMinWidth = 1, sysMinHeight = 1;
    private BoundsType widthType = BoundsType.UNKNOWN;
    private BoundsType heightType = BoundsType.UNKNOWN;
    private int lastMouseX, lastMouseY;
    private double prefHeaderButtonHeight = USE_DEFAULT_HEADER_BUTTON_SIZE;
    private boolean suppressClickRelease;
    private Gtk4IMEHandler imeHandler;
    private final List<SignalConnection> signalConnections = new ArrayList<>();
    private final List<ControllerEntry> installedControllers = new ArrayList<>();

    Gtk4WindowHandler(Gtk4Window jfxWindow, Gtk4WindowHandler owner,
                      FrameType frameType, WindowType windowType) {
        this.jfxWindow = jfxWindow;
        this.owner = owner;
        this.frameType = frameType;
        this.windowType = windowType;
        this.windowArena = Arena.ofShared();
        this.isPopup = (windowType == WindowType.POPUP);

        this.windowSize = new ObservableSize(DEFAULT_WIDTH, DEFAULT_HEIGHT);
        this.viewSize = new ObservableSize(DEFAULT_WIDTH, DEFAULT_HEIGHT);
        windowSize.setOnChange(() -> {
            notifyWindowSize();
            notifyRepaint();
        });
        viewSize.setOnChange(() -> {
            notifyViewResize();
            notifyRepaint();
        });

        if (Gtk4DmaBufCompositor.isAvailable()) {
            this.compositor = new Gtk4DmaBufCompositor();
        } else {
            this.compositor = new Gtk4SoftwareCompositor();
        }
        this.childWidget = compositor.getWidget();

        if (isPopup) {
            this.gtkPopover = GtkPopover.create();
            this.gtkWindow = null;
            this.isAdwWindow = false;

            gtkPopover.setHasArrow(false);
            gtkPopover.setAutohide(false);
            gtkPopover.setCascadePopdown(false);
            gtkPopover.setPosition(GtkPopover.GTK_POS_BOTTOM);

            gtkPopover.addCssClass("jfx-popup");
            ensurePopupCssRegistered();

            gtkPopover.setChild(childWidget);

            if (owner != null) {
                owner.addChild(this);
                gtkPopover.setParent(owner.getGtkWindow());
            }
        } else {
            this.gtkPopover = null;

            if (frameType == FrameType.TRANSPARENT) {
                this.gtkWindow = GtkWindow.create();
                this.isAdwWindow = false;
            } else {
                this.gtkWindow = GtkWindow.createPreferred();
                this.isAdwWindow = GtkWindow.isAdwWindowAvailable();
            }

            configureWindowContent(childWidget);

            gtkWindow.setDefaultSize(DEFAULT_WIDTH, DEFAULT_HEIGHT);

            setTitle("");

            if (owner != null) {
                owner.addChild(this);
                gtkWindow.setTransientFor(owner.gtkWindow);
            }
        }

        installEventControllers();
        connectWindowSignals();
    }

    private static void ensurePopupCssRegistered() {
        if (popupCssRegistered) {
            return;
        }
        popupCssRegistered = true;

        String css =
                """
                        popover.jfx-popup,
                        popover.jfx-popup > contents,
                        popover.jfx-popup > arrow {
                          all: unset;
                          background-color: transparent;
                          background: none;
                          border: none;
                          border-radius: 0;
                          box-shadow: none;
                          margin: 0;
                          padding: 0;
                          min-width: 0;
                          min-height: 0;
                          opacity: 1;
                          color: transparent;
                          -gtk-icon-shadow: none;
                          filter: none;
                        }""";

        GtkCssProvider cssProvider = GtkCssProvider.create();
        cssProvider.loadFromString(css);
        cssProvider.addProviderForDisplay(GdkDisplay.getDefault(), 800);
    }

    private static void ensureTransparentCssRegistered() {
        if (transparentCssRegistered) {
            return;
        }
        transparentCssRegistered = true;

        String css =
                """
                        window.jfx-transparent,
                        window.jfx-transparent * {
                          background-color: transparent;
                          background: none;
                          border: none;
                          border-radius: 0;
                          box-shadow: none;
                          margin: 0;
                          padding: 0;
                        }""";

        GtkCssProvider cssProvider = GtkCssProvider.create();
        cssProvider.loadFromString(css);

        cssProvider.addProviderForDisplay(GdkDisplay.getDefault(), 800);
    }

    private void configureWindowContent(GtkWidget contentWidget) {
        switch (frameType) {
            case TITLED:
                if (isAdwWindow) {
                    headerBar = GtkHeaderBar.createAdw();
                    GtkBox gtkBox = GtkBox.create(GtkBox.GTK_ORIENTATION_VERTICAL, 0);
                    gtkBox.append(headerBar);
                    contentWidget.setVExpand(true);
                    gtkBox.append(contentWidget);
                    gtkWindow.setAdwContent(gtkBox);
                } else {
                    // Plain GtkWindow: add a CSD header bar via titlebar API.
                    headerBar = GtkHeaderBar.create();

                    gtkWindow.setTitlebar(headerBar);
                    gtkWindow.setChild(contentWidget);
                }
                break;
            case UNTITLED:
                setWindowRootContent(contentWidget);
                break;
            case TRANSPARENT:
                configureTransparentRootContent(contentWidget);
                break;
            case EXTENDED:
                configureExtendedRootOverlay(contentWidget);
                break;
        }
    }

    private void configureTransparentRootContent(GtkWidget contentWidget) {
        gtkWindow.setDecorated(false);
        setWindowRootContent(contentWidget);
        gtkWindow.addCssClass("jfx-transparent");
        ensureTransparentCssRegistered();
    }

    private void configureExtendedRootOverlay(GtkWidget contentWidget) {
        windowRootOverlay = GtkOverlay.create();
        // contentWidget remains the real scene content; GtkOverlay is just the root container.
        windowRootOverlay.setChild(contentWidget);

        nativeHeaderControlsStart = GtkWindowControls.create(GtkWindowControls.GTK_PACK_START);

        nativeHeaderControlsStart.setHAlign(GtkWidget.GTK_ALIGN_START);
        nativeHeaderControlsStart.setVAlign(GtkWidget.GTK_ALIGN_START);
        windowRootOverlay.addOverlay(nativeHeaderControlsStart);

        nativeHeaderControlsEnd = GtkWindowControls.create(GtkWindowControls.GTK_PACK_END);

        nativeHeaderControlsEnd.setHAlign(GtkWidget.GTK_ALIGN_END);
        nativeHeaderControlsEnd.setVAlign(GtkWidget.GTK_ALIGN_START);
        windowRootOverlay.addOverlay(nativeHeaderControlsEnd);

        applyNativeHeaderControlsPreferences();
        setWindowRootContent(windowRootOverlay);
    }

    private boolean usesNativeHeaderControls() {
        return frameType == FrameType.EXTENDED
                && nativeHeaderControlsStart != null
                && nativeHeaderControlsEnd != null;
    }

    private void applyNativeHeaderControlsPreferences() {
        if (!usesNativeHeaderControls()) {
            return;
        }

        boolean visible = prefHeaderButtonHeight != 0;


        nativeHeaderControlsStart.setVisible(visible);
        nativeHeaderControlsEnd.setVisible(visible);

        if (visible && prefHeaderButtonHeight > 0) {
            int prefHeight = (int) Math.ceil(prefHeaderButtonHeight);
            nativeHeaderControlsStart.setSizeRequest(-1, prefHeight);
            nativeHeaderControlsEnd.setSizeRequest(-1, prefHeight);
        } else {
            nativeHeaderControlsStart.setSizeRequest(-1, -1);
            nativeHeaderControlsEnd.setSizeRequest(-1, -1);
        }
    }

    void setPrefHeaderButtonHeight(double height) {
        prefHeaderButtonHeight = height;
        applyNativeHeaderControlsPreferences();
        updateNativeHeaderMetrics();
    }

    private void updateNativeHeaderMetrics() {
        if (jfxWindow == null || frameType != FrameType.EXTENDED) {
            return;
        }

        if (!usesNativeHeaderControls() || prefHeaderButtonHeight == 0) {
            setSystemMinimumSize(1, 1);
            jfxWindow.updateNativeHeaderButtonMetrics(0, 0, 0, 0, 0);
            return;
        }


        int startWidth = nativeHeaderControlsStart.getWidth();
        int startHeight = nativeHeaderControlsStart.getHeight();

        int endWidth = nativeHeaderControlsEnd.getWidth();
        int endHeight = nativeHeaderControlsEnd.getHeight();

        boolean startVisible = startWidth > 0 && startHeight > 0;
        boolean endVisible = endWidth > 0 && endHeight > 0;

        int leftWidth = startVisible ? startWidth : 0;
        int leftHeight = startVisible ? startHeight : 0;
        int rightWidth = endVisible ? endWidth : 0;
        int rightHeight = endVisible ? endHeight : 0;
        double measuredMinHeight = Math.max(leftHeight, rightHeight);
        double minHeight = prefHeaderButtonHeight >= 0 ? prefHeaderButtonHeight : measuredMinHeight;

        if (startVisible || endVisible) {
            int minWidth = Math.max(leftWidth + rightWidth, 1);
            int minHeaderHeight = Math.max(Math.max(leftHeight, rightHeight), 1);
            setSystemMinimumSize(minWidth, minHeaderHeight);
            jfxWindow.updateNativeHeaderButtonMetrics(leftWidth, leftHeight, rightWidth, rightHeight, minHeight);
        } else {
            // Before initial map/layout the control can report 0x0.
            setSystemMinimumSize(1, 1);
            jfxWindow.updateNativeHeaderButtonMetrics(0, 0, 0, 0, minHeight);
        }
    }

    private void setWindowRootContent(GtkWidget widget) {
        if (isAdwWindow) {
            gtkWindow.setAdwContent(widget);
        } else {
            gtkWindow.setChild(widget);
        }
    }

    boolean isPopup() {
        return isPopup;
    }

    GtkWidget getChildWidget() {
        return childWidget;
    }

    private GtkWidget topLevelWidget() {
        return isPopup ? gtkPopover : gtkWindow;
    }

    public Gtk4Compositor getCompositor() {
        return compositor;
    }


    private void installEventControllers() {
        GtkWidget toplevel = topLevelWidget();

        GtkEventController focusCtrl = GtkEventController.focusNew();
        toplevel.addController(focusCtrl);
        installedControllers.add(new ControllerEntry(toplevel, focusCtrl));
        connectFocusSignals(focusCtrl);

        GtkEventController keyCtrl = GtkEventController.keyNew();
        toplevel.addController(keyCtrl);
        installedControllers.add(new ControllerEntry(toplevel, keyCtrl));
        connectKeySignals(keyCtrl);

        GtkEventController motionCtrl = GtkEventController.motionNew();
        childWidget.addController(motionCtrl);
        installedControllers.add(new ControllerEntry(childWidget, motionCtrl));
        connectMotionSignals(motionCtrl);

        GtkEventController clickGesture = GtkEventController.gestureClickNew();
        clickGesture.gestureSingleSetButton(0);
        childWidget.addController(clickGesture);
        installedControllers.add(new ControllerEntry(childWidget, clickGesture));
        connectClickSignals(clickGesture);

        GtkEventController scrollCtrl = GtkEventController.scrollNew(3);
        childWidget.addController(scrollCtrl);
        installedControllers.add(new ControllerEntry(childWidget, scrollCtrl));
        connectScrollSignals(scrollCtrl);

        GtkEventController zoomGesture = GtkEventController.gestureZoomNew();
        childWidget.addController(zoomGesture);
        installedControllers.add(new ControllerEntry(childWidget, zoomGesture));
        connectZoomSignals(zoomGesture);

        GtkEventController rotateGesture = GtkEventController.gestureRotateNew();
        childWidget.addController(rotateGesture);
        installedControllers.add(new ControllerEntry(childWidget, rotateGesture));
        connectRotateSignals(rotateGesture);

        GtkEventController swipeGesture = GtkEventController.gestureSwipeNew();
        childWidget.addController(swipeGesture);
        installedControllers.add(new ControllerEntry(childWidget, swipeGesture));
        connectSwipeSignals(swipeGesture);
    }

    private void connectTyped(MemorySegment instance, String signal,
                              MethodHandle typedHandle,
                              FunctionDescriptor descriptor) {
        MethodType typedType = typedHandle.type();
        List<MemoryLayout> nativeLayouts = descriptor.argumentLayouts();
        int nTyped = typedType.parameterCount();
        int nNative = nativeLayouts.size();

        MethodHandle mh = typedHandle;
        if (nNative > nTyped) {
            Class<?>[] extras = new Class<?>[nNative - nTyped];
            java.util.Arrays.fill(extras, MemorySegment.class);
            mh = MethodHandles.dropArguments(mh, nTyped, extras);
        }

        MethodHandle[] filters = new MethodHandle[nNative];
        boolean hasFilters = false;
        for (int i = 0; i < Math.min(nTyped, nNative); i++) {
            Class<?> paramType = typedType.parameterType(i);
            if (GObject.class.isAssignableFrom(paramType)) {
                try {
                    filters[i] = LOOKUP.findConstructor(paramType,
                            MethodType.methodType(void.class, MemorySegment.class));
                    hasFilters = true;
                } catch (NoSuchMethodException | IllegalAccessException e) {
                    throw new RuntimeException("No MemorySegment constructor for " + paramType.getName(), e);
                }
            }
        }
        if (hasFilters) {
            mh = MethodHandles.filterArguments(mh, 0, filters);
        }

        MemorySegment cb = Linker.nativeLinker().upcallStub(mh, descriptor, windowArena);
        long handlerId = GObject.signalConnect(instance, signal, cb);
        signalConnections.add(new SignalConnection(instance, handlerId));
    }

    private void connectTyped(GtkWidget widget, String signal,
                              MethodHandle typedHandle,
                              FunctionDescriptor descriptor) {
        connectTyped(widget.getPointer(), signal, typedHandle, descriptor);
    }

    private MethodHandle typedHandle(String name, Class<?> returnType, Class<?>... paramTypes) {
        try {
            return LOOKUP.bind(this, name, MethodType.methodType(returnType, paramTypes));
        } catch (NoSuchMethodException | IllegalAccessException e) {
            throw new RuntimeException("Cannot find method " + name, e);
        }
    }

    private void connectFocusSignals(GtkEventController controller) {
        var voidPtr = FunctionDescriptor.ofVoid(ValueLayout.ADDRESS);
        connectTyped(controller.getPointer(), "enter",
                typedHandle("onFocusEnter", void.class, GtkEventController.class), voidPtr);
        connectTyped(controller.getPointer(), "leave",
                typedHandle("onFocusLeave", void.class, GtkEventController.class), voidPtr);
    }

    private void connectKeySignals(GtkEventController controller) {
        connectTyped(controller.getPointer(), "key-pressed",
                typedHandle("onKeyPressed", int.class, GtkEventController.class, int.class, int.class, int.class),
                FunctionDescriptor.of(ValueLayout.JAVA_INT,
                        ValueLayout.ADDRESS, ValueLayout.JAVA_INT,
                        ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
        connectTyped(controller.getPointer(), "key-released",
                typedHandle("onKeyReleased", void.class, GtkEventController.class, int.class, int.class, int.class),
                FunctionDescriptor.ofVoid(
                        ValueLayout.ADDRESS, ValueLayout.JAVA_INT,
                        ValueLayout.JAVA_INT, ValueLayout.JAVA_INT));
    }

    private void connectMotionSignals(GtkEventController controller) {
        var voidPtrDblDbl = FunctionDescriptor.ofVoid(
                ValueLayout.ADDRESS, ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE);
        connectTyped(controller.getPointer(), "motion",
                typedHandle("onMotion", void.class, GtkEventController.class, double.class, double.class),
                voidPtrDblDbl);
        connectTyped(controller.getPointer(), "enter",
                typedHandle("onMouseEnter", void.class, GtkEventController.class, double.class, double.class),
                voidPtrDblDbl);
        connectTyped(controller.getPointer(), "leave",
                typedHandle("onMouseLeave", void.class, GtkEventController.class),
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS));
    }

    private void connectClickSignals(GtkEventController gesture) {
        var voidPtrIntDblDbl = FunctionDescriptor.ofVoid(
                ValueLayout.ADDRESS, ValueLayout.JAVA_INT,
                ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE);
        connectTyped(gesture.getPointer(), "pressed",
                typedHandle("onClickPressed", void.class, GtkEventController.class, int.class, double.class, double.class),
                voidPtrIntDblDbl);
        connectTyped(gesture.getPointer(), "released",
                typedHandle("onClickReleased", void.class, GtkEventController.class, int.class, double.class, double.class),
                voidPtrIntDblDbl);
        connectTyped(gesture.getPointer(), "stopped",
                typedHandle("onClickStopped", void.class, GtkEventController.class),
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS));
    }

    private void connectScrollSignals(GtkEventController controller) {
        connectTyped(controller.getPointer(), "scroll",
                typedHandle("onScroll", int.class, GtkEventController.class, double.class, double.class),
                FunctionDescriptor.of(ValueLayout.JAVA_INT,
                        ValueLayout.ADDRESS, ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE));
    }

    private void connectZoomSignals(GtkEventController gesture) {
        var voidPtrPtr = FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS);
        connectTyped(gesture.getPointer(), "begin",
                typedHandle("onZoomBegin", void.class, GtkEventController.class), voidPtrPtr);
        connectTyped(gesture.getPointer(), "scale-changed",
                typedHandle("onZoomScaleChanged", void.class, GtkEventController.class, double.class),
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.JAVA_DOUBLE));
        connectTyped(gesture.getPointer(), "end",
                typedHandle("onZoomEnd", void.class, GtkEventController.class), voidPtrPtr);
    }

    private void connectRotateSignals(GtkEventController gesture) {
        var voidPtrPtr = FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS);
        connectTyped(gesture.getPointer(), "begin",
                typedHandle("onRotateBegin", void.class, GtkEventController.class), voidPtrPtr);
        connectTyped(gesture.getPointer(), "angle-changed",
                typedHandle("onRotateAngleChanged", void.class, GtkEventController.class, double.class, double.class),
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE));
        connectTyped(gesture.getPointer(), "end",
                typedHandle("onRotateEnd", void.class, GtkEventController.class), voidPtrPtr);
    }

    private void connectSwipeSignals(GtkEventController gesture) {
        connectTyped(gesture.getPointer(), "swipe",
                typedHandle("onSwipe", void.class, GtkEventController.class, double.class, double.class),
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE));
    }

    private void connectWindowSignals() {
        GtkWidget widget = topLevelWidget();

        if (!isPopup) {
            var voidPtrPtrPtr = FunctionDescriptor.ofVoid(
                    ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS);

            connectTyped(gtkWindow.getPointer(), "close-request",
                    typedHandle("onCloseRequest", int.class, GtkWindow.class),
                    FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS, ValueLayout.ADDRESS));
            connectTyped(gtkWindow.getPointer(), "notify::maximized",
                    typedHandle("onMaximizedChanged", void.class, GtkWindow.class), voidPtrPtrPtr);
            connectTyped(gtkWindow.getPointer(), "notify::fullscreened",
                    typedHandle("onFullscreenChanged", void.class, GtkWindow.class), voidPtrPtrPtr);
            connectTyped(gtkWindow.getPointer(), "notify::scale-factor",
                    typedHandle("onScaleFactorChanged", void.class, GtkWidget.class), voidPtrPtrPtr);
            connectTyped(gtkWindow.getPointer(), "notify::is-active",
                    typedHandle("onActiveChanged", void.class, GtkWindow.class), voidPtrPtrPtr);
        }

        var voidPtrPtr = FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.ADDRESS);

        connectTyped(widget, "realize",
                typedHandle("onRealize", void.class, GtkWidget.class), voidPtrPtr);
        connectTyped(widget, "map",
                typedHandle("onMap", void.class, GtkWidget.class), voidPtrPtr);
        connectTyped(widget, "unmap",
                typedHandle("onUnmap", void.class, GtkWidget.class), voidPtrPtr);
    }

    private void connectSurfaceSignals(GdkSurface surface) {
        connectTyped(surface.getPointer(), "layout",
                typedHandle("onSurfaceLayout", void.class, GdkSurface.class, int.class, int.class),
                FunctionDescriptor.ofVoid(ValueLayout.ADDRESS, ValueLayout.JAVA_INT,
                        ValueLayout.JAVA_INT, ValueLayout.ADDRESS));
        var voidPtrPtrPtr = FunctionDescriptor.ofVoid(
                ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS);
        connectTyped(surface.getPointer(), "enter-monitor",
                typedHandle("onEnterMonitor", void.class, GdkSurface.class, GdkMonitor.class), voidPtrPtrPtr);
        connectTyped(surface.getPointer(), "leave-monitor",
                typedHandle("onLeaveMonitor", void.class, GdkSurface.class, GdkMonitor.class), voidPtrPtrPtr);
    }
    private int getGlassModifiers(GtkEventController controller) {
        GdkEvent event = controller.getCurrentEvent();
        if (event == null) {
            return 0;
        }
        return Gtk4KeyMap.toGlassModifier(event.getModifierState());
    }

    private void logNotify(String notifyName) {
        System.out.println("[Gtk4WindowContext] " + notifyName);
    }

    private void logNotify(String notifyName, String details) {
        System.out.println("[Gtk4WindowContext] " + notifyName + " " + details);
    }

    void onFocusEnter(GtkEventController controller) {
    }


    void onFocusLeave(GtkEventController controller) {
    }


    int onKeyPressed(GtkEventController controller, int keyval, int keycode, int state) {
        if (jfxWindow == null) return 0;
        GdkEvent event = controller.getCurrentEvent();
        if (imeHandler != null && imeHandler.filter(event)) {
            return 1;
        }
        jfxWindow.notifyKeyEvent(true, keyval, keycode, state);
        return 0;
    }


    void onKeyReleased(GtkEventController controller, int keyval, int keycode, int state) {
        if (jfxWindow == null) return;
        GdkEvent event = controller.getCurrentEvent();
        if (imeHandler != null && imeHandler.filter(event)) {
            return;
        }
        jfxWindow.notifyKeyEvent(false, keyval, keycode, state);
    }


    void onMotion(GtkEventController controller, double x, double y) {
        int ix = (int) x;
        int iy = (int) y;
        lastMouseX = ix;
        lastMouseY = iy;
        if (jfxWindow == null) return;
        int modifiers = getGlassModifiers(controller);
        jfxWindow.notifyMouseMotion(ix, iy, 0, 0, modifiers);
    }


    void onMouseEnter(GtkEventController controller, double x, double y) {
        mouseEntered = true;
        int ix = (int) x;
        int iy = (int) y;
        lastMouseX = ix;
        lastMouseY = iy;
        if (jfxWindow == null) return;
        int modifiers = getGlassModifiers(controller);
        jfxWindow.notifyMouseEnter(ix, iy, ix, iy, modifiers);
    }


    void onMouseLeave(GtkEventController controller) {
        mouseEntered = false;
        if (jfxWindow == null) return;
        int modifiers = getGlassModifiers(controller);
        jfxWindow.notifyMouseExit(lastMouseX, lastMouseY, 0, 0, modifiers);
    }


    void onClickPressed(GtkEventController gesture, int nPress, double x, double y) {
        checkUngrab();

        if (jfxWindow != null) {
            int gdkButton = gesture.gestureSingleGetCurrentButton();
            if (gdkButton == 0) {
                return;
            }
            int ix = (int) x;
            int iy = (int) y;
            lastMouseX = ix;
            lastMouseY = iy;

            if (beginNativeWindowMove(gesture, gdkButton, ix, iy)) {
                return;
            }

            int modifiers = getGlassModifiers(gesture);
            logNotify("notifyMouseButton(pressed)",
                    "button=" + gdkButton + " nPress=" + nPress
                            + " x=" + ix + " y=" + iy
                            + " modifiers=" + modifiers);
            jfxWindow.notifyMouseButton(true, gdkButton, ix, iy,
                    ix, iy, modifiers);
        }
    }


    void onClickReleased(GtkEventController gesture, int nPress, double x, double y) {
        int gdkButton = gesture.gestureSingleGetCurrentButton();
        if (gdkButton == 0) {
            return;
        }

        if (suppressClickRelease && gdkButton == 1) {
            suppressClickRelease = false;
            return;
        }

        int ix = (int) x;
        int iy = (int) y;
        int modifiers = getGlassModifiers(gesture);
        logNotify("notifyMouseButton(released)",
                "button=" + gdkButton + " nPress=" + nPress
                        + " x=" + ix + " y=" + iy
                        + " modifiers=" + modifiers);
        jfxWindow.notifyMouseButton(false, gdkButton, ix, iy,
                0, 0, modifiers);
    }


    void onClickStopped(GtkEventController gesture) {
    }


    int onScroll(GtkEventController controller, double dx, double dy) {
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(controller);
            logNotify("notifyScroll",
                    "x=" + lastMouseX + " y=" + lastMouseY
                            + " dx=" + dx + " dy=" + dy + " modifiers=" + modifiers);
            jfxWindow.notifyScroll(lastMouseX, lastMouseY,
                    0, 0, dx, dy, modifiers);
        }
        return 0;
    }

    private double zoomTotalScale;
    private double zoomLastScale;


    void onZoomBegin(GtkEventController gesture) {
        zoomTotalScale = 1.0;
        zoomLastScale = 1.0;
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(gesture);
            jfxWindow.notifyZoomGesture(GestureEvent.GESTURE_STARTED, modifiers,
                    lastMouseX, lastMouseY, 0, 0,
                    1.0, 0.0, 1.0, 0.0);
        }
    }


    void onZoomScaleChanged(GtkEventController gesture, double scale) {
        if (jfxWindow != null) {
            double delta = scale / zoomLastScale;
            zoomLastScale = scale;
            zoomTotalScale = scale;
            double expansion = scale - 1.0;
            double totalExpansion = zoomTotalScale - 1.0;
            int modifiers = getGlassModifiers(gesture);
            jfxWindow.notifyZoomGesture(GestureEvent.GESTURE_PERFORMED, modifiers,
                    lastMouseX, lastMouseY, 0, 0,
                    delta, expansion, zoomTotalScale, totalExpansion);
        }
    }

    @SuppressWarnings("unused")
    void onZoomEnd(MemorySegment gesture, MemorySegment sequence) {
        onZoomEnd(new GtkEventController(gesture));
    }

    void onZoomEnd(GtkEventController gesture) {
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(gesture);
            jfxWindow.notifyZoomGesture(GestureEvent.GESTURE_FINISHED, modifiers,
                    lastMouseX, lastMouseY, 0, 0,
                    1.0, 0.0, zoomTotalScale, zoomTotalScale - 1.0);
        }
        zoomTotalScale = 1.0;
        zoomLastScale = 1.0;
    }

    private double rotateTotalAngle;
    private double rotateLastAngle;

    @SuppressWarnings("unused")
    void onRotateBegin(MemorySegment gesture, MemorySegment sequence) {
        onRotateBegin(new GtkEventController(gesture));
    }

    void onRotateBegin(GtkEventController gesture) {
        rotateTotalAngle = 0.0;
        rotateLastAngle = 0.0;
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(gesture);
            jfxWindow.notifyRotateGesture(GestureEvent.GESTURE_STARTED, modifiers,
                    lastMouseX, lastMouseY, 0, 0,
                    0.0, 0.0);
        }
    }

    @SuppressWarnings("unused")
    void onRotateAngleChanged(MemorySegment gesture, double angle, double angleDelta) {
        onRotateAngleChanged(new GtkEventController(gesture), angle, angleDelta);
    }

    void onRotateAngleChanged(GtkEventController gesture, double angle, double angleDelta) {
        if (jfxWindow != null) {
            double degrees = Math.toDegrees(angleDelta);
            rotateTotalAngle += degrees;
            int modifiers = getGlassModifiers(gesture);
            jfxWindow.notifyRotateGesture(GestureEvent.GESTURE_PERFORMED, modifiers,
                    lastMouseX, lastMouseY, 0, 0,
                    degrees, rotateTotalAngle);
        }
    }

    @SuppressWarnings("unused")
    void onRotateEnd(MemorySegment gesture, MemorySegment sequence) {
        onRotateEnd(new GtkEventController(gesture));
    }

    void onRotateEnd(GtkEventController gesture) {
        if (jfxWindow != null) {
            int modifiers = getGlassModifiers(gesture);
            jfxWindow.notifyRotateGesture(GestureEvent.GESTURE_FINISHED, modifiers,
                    lastMouseX, lastMouseY, 0, 0,
                    0.0, rotateTotalAngle);
        }
        rotateTotalAngle = 0.0;
        rotateLastAngle = 0.0;
    }

    @SuppressWarnings("unused")
    void onSwipe(MemorySegment gesture, double velocityX, double velocityY) {
        onSwipe(new GtkEventController(gesture), velocityX, velocityY);
    }

    void onSwipe(GtkEventController gesture, double velocityX, double velocityY) {
        if (jfxWindow != null) {
            int dir;
            if (Math.abs(velocityX) > Math.abs(velocityY)) {
                dir = (velocityX > 0) ? SwipeGesture.DIR_RIGHT : SwipeGesture.DIR_LEFT;
            } else {
                dir = (velocityY > 0) ? SwipeGesture.DIR_DOWN : SwipeGesture.DIR_UP;
            }
            int modifiers = getGlassModifiers(gesture);
            jfxWindow.notifySwipeGesture(GestureEvent.GESTURE_PERFORMED, modifiers,
                    lastMouseX, lastMouseY, 0, 0, dir);
        }
    }

