    boolean grabFocus() {
        if (grabWindow == this) {
            return true;
        }

        if (grabWindow != null) {
            grabWindow.ungrabFocus();
        }

        boolean grabbed = topLevelWidget().grabFocus();
        if (grabbed) {
            grabWindow = this;
        }
        return grabbed;
    }

    void ungrabFocus() {
        if (grabWindow != this) {
            return;
        }

        grabWindow = null;

        if (!isPopup && gtkWindow != null) {
            gtkWindow.setFocus(null);
        }

        if (jfxWindow != null) {
            jfxWindow.notifyFocusUngrabEvent();
        }
    }

    private void checkUngrab() {
        if (grabWindow == null) {
            return;
        }

        for (Gtk4WindowHandler hnd = this; hnd != null; hnd = hnd.owner) {
            if (hnd == grabWindow) {
                return;
            }
        }

        grabWindow.ungrabFocus();
    }

