    public void setIcon(int width, int height, int[] pixels) {
        // In GTK4, window icons are set via a GdkPaintable (GdkTexture)
        // This requires creating a GdkMemoryTexture from pixel data
        if (pixels == null || width <= 0 || height <= 0) {
            return;
        }

        try (Arena arena = Arena.ofConfined()) {
            // ARGB32 pixels → copy to native memory
            long dataSize = (long) width * height * 4;
            MemorySegment nativeData = arena.allocate(dataSize);
            for (int i = 0; i < width * height; i++) {
                nativeData.setAtIndex(ValueLayout.JAVA_INT, i, pixels[i]);
            }

            MemorySegment gbytes = GLib.bytesNew(nativeData, dataSize);
            // GDK_MEMORY_B8G8R8A8_PREMULTIPLIED = 0 (approximately; depends on endianness)
            MemorySegment texture = GdkMemoryTexture.create(width, height,
                    GdkMemoryTexture.GDK_MEMORY_B8G8R8A8_PREMULTIPLIED,
                    gbytes, (long) width * 4).getPointer();
            GLib.bytesUnref(gbytes);

            // GTK4: gtk_window_set_icon_name is the primary API but doesn't accept paintable directly.
            // For custom pixel icons, we'd need to register a named icon or use a different approach.
            // This is a simplified implementation.
        }
    }

    public void setBounds(int x, int y, boolean xSet, boolean ySet,
                          int w, int h, int cw, int ch,
                          float gravityX, float gravityY) {
        int extW = Math.max(windowSize.width() - viewSize.width(), 0);
        int extH = Math.max(windowSize.height() - viewSize.height(), 0);

        int newW = 0;
        int newH = 0;

        if (w > 0) {
            widthType = BoundsType.WINDOW;
            newW = w - extW;
        } else if (cw > 0) {
            widthType = BoundsType.VIEW;
            newW = cw;
        } else {
            newW = viewSize.width();
        }

        if (h > 0) {
            heightType = BoundsType.WINDOW;
            newH = h - extH;
        } else if (ch > 0) {
            heightType = BoundsType.VIEW;
            newH = ch;
        } else {
            newH = viewSize.height();
        }

        if (newW > 0 || newH > 0) {
            updateSizeConstraints();

            if (isPopup) {
                childWidget.setSizeRequest(Math.max(newW, 1), Math.max(newH, 1));
            } else {
                gtkWindow.setDefaultSize(Math.max(newW, 1), Math.max(newH, 1));
            }

            sizeAssigned = true;

            updateWindowSize();
            if (topLevelWidget().getWidth() <= 0) {
                windowSize.set(Math.max(newW + extW, 1), Math.max(newH + extH, 1));
                viewSize.set(Math.max(newW, 1), Math.max(newH, 1));
            }
        }

        if (xSet || ySet) {
            if (isPopup) {
                int popX = xSet ? x : 0;
                int popY = ySet ? y : 0;
                System.out.println("Popup position: " + popX + ", " + popY);
                if (owner != null) {
                    int ownerW = Math.max(owner.viewSize.width(), 1);
                    int ownerH = Math.max(owner.viewSize.height(), 1);
                    popX = Math.clamp(popX, 0, ownerW);
                    popY = Math.clamp(popY, 0, ownerH);
                }
                System.out.println("Popup position: " + popX + ", " + popY);

                gtkPopover.setPointingTo(popX, popY, viewSize.width(), viewSize.height());
                gtkPopover.setOffset(viewX, viewY);
                System.out.println("Popup Offset " + viewX + ", " + viewY);
            }

            notifyWindowMove();
        }
    }

    private void updateWindowSize() {
        GtkWidget toplevel = topLevelWidget();
        windowSize.set(toplevel.getWidth(), toplevel.getHeight());
        viewSize.set(childWidget.getWidth(), childWidget.getHeight());
        updateViewPosition();
    }

    private void updateViewPosition() {
        if (jfxWindow == null) {
            return;
        }
        viewX = Math.max(windowSize.width() - viewSize.width(), 0);
        viewY = Math.max(windowSize.height() - viewSize.height(), 0);
        jfxWindow.notifyViewPosition(viewX, viewY);
    }

