    private void notifyWindowMove() {
        if (jfxWindow == null) {
            return;
        }
        // Wayland does not expose absolute window positions.
        // Always report (0, 0).
        jfxWindow.notifyMoveEvent(0, 0);
        jfxWindow.notifyMoveEvent(0, 0);
    }

