//        logNotify("notifyViewRepaint");
        jfxWindow.notifyViewRepaint();
    }

    private boolean beginNativeWindowMove(GtkEventController gesture, int gdkButton, int x, int y) {
        if (frameType != FrameType.EXTENDED || gdkButton != 1 || !isFloating() || jfxWindow == null) {
            return false;
        }

        int localPhysicalX = (int) Math.round(x * jfxWindow.getPlatformScaleX());
        int localPhysicalY = (int) Math.round(y * jfxWindow.getPlatformScaleY());
        if (jfxWindow.nonClientHitTest(localPhysicalX, localPhysicalY) != HT_CAPTION) {
            return false;
        }

        if (gdkToplevel == null) {
            return false;
        }

        GdkEvent event = gesture.getCurrentEvent();
        if (event == null) {
            return false;
        }

        MemorySegment device = event.getDevice();
        if (device == null || device.equals(MemorySegment.NULL)) {
            return false;
        }

        gdkToplevel.beginMove(device, gdkButton, x, y, event.getTime());
        suppressClickRelease = true;
        return true;
    }

    public void updateViewSize() {
        notifyViewResize();
        notifyRepaint();
    }

