    public void destroy() {
        if (destroyed) {
            return;
        }
        destroyed = true;

        disableIME();

        if (grabWindow == this) {
            ungrabFocus();
        }

        gdkToplevel = null;

        compositor.dispose();

        if (owner != null) {
            owner.removeChild(this);
        }

        for (Gtk4WindowHandler child : new HashSet<>(children)) {
            child.setOwner(null);
            child.destroy();
        }
        children.clear();

        if (jfxWindow != null) {
//            logNotify("notifyDestroyEvent");
            jfxWindow.notifyDestroyEvent();
        }

        disconnectAllSignals();
        removeAllControllers();

        if (isPopup) {
            gtkPopover.unparent();
        } else {
            gtkWindow.destroy();
        }
        windowArena.close();
    }

    private void disconnectAllSignals() {
        for (SignalConnection sc : signalConnections) {
            GObject.signalHandlerDisconnect(sc.instance(), sc.handlerId());
        }
        signalConnections.clear();
    }

    private void removeAllControllers() {
        for (ControllerEntry ce : installedControllers) {
            ce.widget().removeController(ce.controller());
        }
        installedControllers.clear();
    }

    enum FrameType {
        TITLED,
        UNTITLED,
        TRANSPARENT,
        EXTENDED
    }

    enum WindowType {
        NORMAL,
        UTILITY,
        POPUP
    }

    private enum BoundsType {
        UNKNOWN,
        VIEW,
        WINDOW
    }

    private static final class ObservableSize {
        private int width;
        private int height;
        private Runnable onChange;

        ObservableSize(int width, int height) {
            this.width = width;
            this.height = height;
        }

        void setOnChange(Runnable onChange) {
            this.onChange = onChange;
        }

        int width() {
            return width;
        }

        int height() {
            return height;
        }

        boolean set(int w, int h) {
            boolean changed = false;
            if (w > 0) {
                int clamped = Math.clamp(w, 1, MAX_WINDOW_SIZE);
                if (clamped != width) {
                    width = clamped;
                    changed = true;
                }
            }
            if (h > 0) {
                int clamped = Math.clamp(h, 1, MAX_WINDOW_SIZE);
                if (clamped != height) {
                    height = clamped;
                    changed = true;
                }
            }
            if (changed && onChange != null) {
                onChange.run();
            }
            return changed;
        }

        void notifyListeners() {
            if (onChange != null) {
                onChange.run();
            }
        }
    }

    private record SignalConnection(MemorySegment instance, long handlerId) {}

    private record ControllerEntry(GtkWidget widget, GtkEventController controller) {}
}

