    private void applyInitialState() {
        if (isPopup || initialState == 0) {
            return;
        }
        int state = initialState;
        initialState = 0;
        if ((state & INITIAL_STATE_FULLSCREEN) != 0) {
            enterFullscreen();
        }
        if ((state & INITIAL_STATE_MAXIMIZED) != 0) {
            setMaximized(true);
        }
        if ((state & INITIAL_STATE_ICONIFIED) != 0) {
            setMinimized(true);
        }
    }

