    public void setIcon(int width, int height, int[] pixels) {
        // In GTK4, window icons are set via a GdkPaintable (GdkTexture)
        // This requires creating a GdkMemoryTexture from pixel data
        if (pixels == null || width <= 0 || height <= 0) {
            return;
        }

        try (Arena arena = Arena.ofConfined()) {
            // ARGB32 pixels → copy to native memory
            long dataSize = (long) width * height * 4;
            MemorySegment nativeData = arena.allocate(dataSize);
            for (int i = 0; i < width * height; i++) {
                nativeData.setAtIndex(ValueLayout.JAVA_INT, i, pixels[i]);
            }

            MemorySegment gbytes = GLib.bytesNew(nativeData, dataSize);
            // GDK_MEMORY_B8G8R8A8_PREMULTIPLIED = 0 (approximately; depends on endianness)
            MemorySegment texture = GdkMemoryTexture.create(width, height,
                    GdkMemoryTexture.GDK_MEMORY_B8G8R8A8_PREMULTIPLIED,
                    gbytes, (long) width * 4).getPointer();
            GLib.bytesUnref(gbytes);

            // GTK4: gtk_window_set_icon_name is the primary API but doesn't accept paintable directly.
            // For custom pixel icons, we'd need to register a named icon or use a different approach.
            // This is a simplified implementation.
        }
    }

    public void setBounds(int x, int y, boolean xSet, boolean ySet,
                          int w, int h, int cw, int ch,
                          float gravityX, float gravityY) {
        int extW = Math.max(windowSize.width() - viewSize.width(), 0);
        int extH = Math.max(windowSize.height() - viewSize.height(), 0);

        int newW = 0;
        int newH = 0;

        if (w > 0) {
            widthType = BoundsType.WINDOW;
            newW = w - extW;
        } else if (cw > 0) {
            widthType = BoundsType.VIEW;
            newW = cw;
        } else {
            newW = viewSize.width();
        }

        if (h > 0) {
            heightType = BoundsType.WINDOW;
            newH = h - extH;
        } else if (ch > 0) {
            heightType = BoundsType.VIEW;
            newH = ch;
        } else {
            newH = viewSize.height();
        }

        if (newW > 0 || newH > 0) {
            updateSizeConstraints();

            if (isPopup) {
                childWidget.setSizeRequest(Math.max(newW, 1), Math.max(newH, 1));
            } else {
                gtkWindow.setDefaultSize(Math.max(newW, 1), Math.max(newH, 1));
            }

            sizeAssigned = true;

            updateWindowSize();
            if (topLevelWidget().getWidth() <= 0) {
                windowSize.set(Math.max(newW + extW, 1), Math.max(newH + extH, 1));
                viewSize.set(Math.max(newW, 1), Math.max(newH, 1));
            }
        }

        if (xSet || ySet) {
            if (isPopup) {
                int popX = xSet ? x : 0;
                int popY = ySet ? y : 0;
                System.out.println("Popup position: " + popX + ", " + popY);
                if (owner != null) {
                    int ownerW = Math.max(owner.viewSize.width(), 1);
                    int ownerH = Math.max(owner.viewSize.height(), 1);
                    popX = Math.clamp(popX, 0, ownerW);
                    popY = Math.clamp(popY, 0, ownerH);
                }
                System.out.println("Popup position: " + popX + ", " + popY);

                gtkPopover.setPointingTo(popX, popY, viewSize.width(), viewSize.height());
                gtkPopover.setOffset(viewX, viewY);
                System.out.println("Popup Offset " + viewX + ", " + viewY);
            }

            notifyWindowMove();
        }
    }

    private void updateWindowSize() {
        GtkWidget toplevel = topLevelWidget();
        windowSize.set(toplevel.getWidth(), toplevel.getHeight());
        viewSize.set(childWidget.getWidth(), childWidget.getHeight());
        updateViewPosition();
    }

    private void updateViewPosition() {
        if (jfxWindow == null) {
            return;
        }
        viewX = Math.max(windowSize.width() - viewSize.width(), 0);
        viewY = Math.max(windowSize.height() - viewSize.height(), 0);
        jfxWindow.notifyViewPosition(viewX, viewY);
    }

    void addChild(Gtk4WindowHandler child) {
        children.add(child);
    }

    void removeChild(Gtk4WindowHandler child) {
        children.remove(child);
    }

    void setOwner(Gtk4WindowHandler newOwner) {
        this.owner = newOwner;
    }

    private void notifyWindowSize() {
        if (jfxWindow == null) {
            return;
        }

//        logNotify("notifyResizeEvent", "width=" + windowSize.width() + " height=" + windowSize.height());
        jfxWindow.notifyResizeEvent(windowSize.width(), windowSize.height());
    }

    private void notifyViewResize() {
        if (jfxWindow == null) {
            return;
        }

//        logNotify("notifyViewResize", "width=" + viewSize.width() + " height=" + viewSize.height());
        jfxWindow.notifyViewResize(viewSize.width(), viewSize.height());
    }

    private void notifyWindowMove() {
        if (jfxWindow == null) {
            return;
        }
        // Wayland does not expose absolute window positions.
        // Always report (0, 0).
        jfxWindow.notifyMoveEvent(0, 0);
        jfxWindow.notifyMoveEvent(0, 0);
    }

    private void notifyRepaint() {
        if (jfxWindow == null) {
            return;
        }

//        logNotify("notifyViewRepaint");
        jfxWindow.notifyViewRepaint();
    }

    private boolean beginNativeWindowMove(GtkEventController gesture, int gdkButton, int x, int y) {
        if (frameType != FrameType.EXTENDED || gdkButton != 1 || !isFloating() || jfxWindow == null) {
            return false;
        }

        int localPhysicalX = (int) Math.round(x * jfxWindow.getPlatformScaleX());
        int localPhysicalY = (int) Math.round(y * jfxWindow.getPlatformScaleY());
        if (jfxWindow.nonClientHitTest(localPhysicalX, localPhysicalY) != HT_CAPTION) {
            return false;
        }

        if (gdkToplevel == null) {
            return false;
        }

        GdkEvent event = gesture.getCurrentEvent();
        if (event == null) {
            return false;
        }

        MemorySegment device = event.getDevice();
        if (device == null || device.equals(MemorySegment.NULL)) {
            return false;
        }

        gdkToplevel.beginMove(device, gdkButton, x, y, event.getTime());
        suppressClickRelease = true;
        return true;
    }

    public void updateViewSize() {
        notifyViewResize();
        notifyRepaint();
    }

    public int getViewWidth() {
        return viewSize.width();
    }

    public int getViewHeight() {
        return viewSize.height();
    }

    void enableOrResetIME() {
        if (imeHandler == null) {
            imeHandler = new Gtk4IMEHandler(jfxWindow, topLevelWidget(), windowArena);
        }
        imeHandler.enableOrResetIME();
    }

    void disableIME() {
        if (imeHandler != null) {
            imeHandler.disable();
            imeHandler = null;
        }
    }

    boolean hasIME() {
        return imeHandler != null && imeHandler.isEnabled();
    }

    public void destroy() {
        if (destroyed) {
            return;
        }
        destroyed = true;

        disableIME();

        if (grabWindow == this) {
            ungrabFocus();
        }

        gdkToplevel = null;

        compositor.dispose();

        if (owner != null) {
            owner.removeChild(this);
        }

        for (Gtk4WindowHandler child : new HashSet<>(children)) {
            child.setOwner(null);
            child.destroy();
        }
        children.clear();

        if (jfxWindow != null) {
//            logNotify("notifyDestroyEvent");
            jfxWindow.notifyDestroyEvent();
        }

        disconnectAllSignals();
        removeAllControllers();

        if (isPopup) {
            gtkPopover.unparent();
        } else {
            gtkWindow.destroy();
        }
        windowArena.close();
    }

    private void disconnectAllSignals() {
        for (SignalConnection sc : signalConnections) {
            GObject.signalHandlerDisconnect(sc.instance(), sc.handlerId());
        }
        signalConnections.clear();
    }

    private void removeAllControllers() {
        for (ControllerEntry ce : installedControllers) {
            ce.widget().removeController(ce.controller());
        }
        installedControllers.clear();
    }

    enum FrameType {
        TITLED,
        UNTITLED,
        TRANSPARENT,
        EXTENDED
    }

    enum WindowType {
        NORMAL,
        UTILITY,
        POPUP
    }

    private enum BoundsType {
        UNKNOWN,
        VIEW,
        WINDOW
    }

    private static final class ObservableSize {
        private int width;
        private int height;
        private Runnable onChange;

        ObservableSize(int width, int height) {
            this.width = width;
            this.height = height;
        }

        void setOnChange(Runnable onChange) {
            this.onChange = onChange;
        }

        int width() {
            return width;
        }

        int height() {
            return height;
        }

        boolean set(int w, int h) {
            boolean changed = false;
            if (w > 0) {
                int clamped = Math.clamp(w, 1, MAX_WINDOW_SIZE);
                if (clamped != width) {
                    width = clamped;
                    changed = true;
                }
            }
            if (h > 0) {
                int clamped = Math.clamp(h, 1, MAX_WINDOW_SIZE);
                if (clamped != height) {
                    height = clamped;
                    changed = true;
                }
            }
            if (changed && onChange != null) {
                onChange.run();
            }
            return changed;
        }

        void notifyListeners() {
            if (onChange != null) {
                onChange.run();
            }
        }
    }

    private record SignalConnection(MemorySegment instance, long handlerId) {}

    private record ControllerEntry(GtkWidget widget, GtkEventController controller) {}
}

