    private static final class LibPortalHolder {
        static final SymbolLookup LOOKUP;
        static final boolean AVAILABLE;

        static {
            SymbolLookup lib = null;
            boolean avail = false;
            try {
                lib = SymbolLookup.libraryLookup("libportal.so.1", Arena.global());
                avail = true;
            } catch (IllegalArgumentException | UnsatisfiedLinkError e1) {
                try {
                    lib = SymbolLookup.libraryLookup("libportal.so", Arena.global());
                    avail = true;
                } catch (IllegalArgumentException | UnsatisfiedLinkError ignored) {
                }
            }
            LOOKUP = lib;
            AVAILABLE = avail;
