    public static String takeScreenshotSync(MemorySegment portal) {
        ScreenshotCallback cb = new ScreenshotCallback();
        cb.portal = portal;

        try (Arena arena = Arena.ofConfined()) {
            MethodHandle mh;
            try {
                mh = MethodHandles.lookup().bind(cb, "onReady",
                        MethodType.methodType(void.class,
