                    FunctionDescriptor.ofVoid(
                            ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                    arena);

            invokeVoid(H.TAKE_SCREENSHOT,
                    portal, MemorySegment.NULL, 0,
                    MemorySegment.NULL, stub, MemorySegment.NULL);

            MethodHandle trueHandle = MethodHandles.dropArguments(
                    MethodHandles.constant(int.class, 1), 0, MemorySegment.class);
            MemorySegment wakeupStub = Linker.nativeLinker().upcallStub(trueHandle,
                    FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS), arena);
            int wakeupId = GLib.timeoutAddFull(GLib.G_PRIORITY_HIGH_IDLE,
                    WAKEUP_INTERVAL_MS, wakeupStub, MemorySegment.NULL, MemorySegment.NULL);

            try {
                long deadline = System.currentTimeMillis() + SCREENSHOT_TIMEOUT_MS;
                while (!cb.done) {
                    if (System.currentTimeMillis() > deadline) {
                        throw new RuntimeException("Screenshot request timed out");
                    }
                    GLib.mainContextIteration(true);
                }
            } finally {
                GLib.sourceRemove(wakeupId);
            }
        }

        if (cb.error != null) {
            throw cb.error;
        }
        return cb.uri;
    }

    static final class ScreenshotCallback {
        MemorySegment portal;
        String uri;
        RuntimeException error;
        volatile boolean done;

        public void onReady(MemorySegment source, MemorySegment asyncResult, MemorySegment userData) {
            try (Arena a = Arena.ofConfined()) {
                MemorySegment errorPtr = a.allocate(ValueLayout.ADDRESS);
                MemorySegment uriSeg = invokePointer(H.TAKE_SCREENSHOT_FINISH,
                        portal, asyncResult, errorPtr);
                MemorySegment err = errorPtr.get(ValueLayout.ADDRESS, 0);
                if (err.address() != 0) {
                    error = new RuntimeException("Screenshot portal request failed");
                } else if (uriSeg != null && uriSeg.address() != 0) {
                    uri = GLib.toJavaString(uriSeg);
                    GLib.free(uriSeg);
                } else {
                    error = new RuntimeException("Screenshot returned null URI");
                }
            }
            done = true;
        }
    }

    public static MemorySegment createRemoteDesktopSessionSync(MemorySegment portal, int devices) {
        RemoteDesktopCallback cb = new RemoteDesktopCallback();
        cb.portal = portal;

        try (Arena arena = Arena.ofConfined()) {
            MethodHandle mh;
            try {
                mh = MethodHandles.lookup().bind(cb, "onReady",
                        MethodType.methodType(void.class,
                                MemorySegment.class, MemorySegment.class, MemorySegment.class));
            } catch (NoSuchMethodException | IllegalAccessException e) {
                throw new RuntimeException(e);
            }

            MemorySegment stub = Linker.nativeLinker().upcallStub(mh,
                    FunctionDescriptor.ofVoid(
                            ValueLayout.ADDRESS, ValueLayout.ADDRESS, ValueLayout.ADDRESS),
                    arena);

            invokeVoid(H.CREATE_REMOTE_DESKTOP_SESSION,
                    portal, devices, XDP_OUTPUT_NONE, XDP_REMOTE_DESKTOP_FLAG_NONE,
                    XDP_CURSOR_MODE_HIDDEN,
                    MemorySegment.NULL, stub, MemorySegment.NULL);

            MethodHandle trueHandle = MethodHandles.dropArguments(
                    MethodHandles.constant(int.class, 1), 0, MemorySegment.class);
            MemorySegment wakeupStub = Linker.nativeLinker().upcallStub(trueHandle,
                    FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS), arena);
            int wakeupId = GLib.timeoutAddFull(GLib.G_PRIORITY_HIGH_IDLE,
                    WAKEUP_INTERVAL_MS, wakeupStub, MemorySegment.NULL, MemorySegment.NULL);

            try {
                long deadline = System.currentTimeMillis() + REMOTE_DESKTOP_TIMEOUT_MS;
                while (!cb.done) {
                    if (System.currentTimeMillis() > deadline) {
                        throw new RuntimeException("RemoteDesktop session request timed out");
                    }
                    GLib.mainContextIteration(true);
                }
            } finally {
                GLib.sourceRemove(wakeupId);
            }
        }

        if (cb.error != null) {
            throw cb.error;
        }
        return cb.session;
    }

    public static int sessionConnectToEis(MemorySegment session) {
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment errorPtr = arena.allocate(ValueLayout.ADDRESS);
            int fd = NativeSymbolLookup.invokeInt(H.SESSION_CONNECT_TO_EIS, session, errorPtr);
            MemorySegment err = errorPtr.get(ValueLayout.ADDRESS, 0);
            if (err.address() != 0) {
                return -1;
            }
            return fd;
        }
    }

    public static void sessionClose(MemorySegment session) {
        if (session != null && session.address() != 0) {
            invokeVoid(H.SESSION_CLOSE, session);
        }
    }

    static final class RemoteDesktopCallback {
        MemorySegment portal;
        MemorySegment session;
        RuntimeException error;
        volatile boolean done;

        public void onReady(MemorySegment source, MemorySegment asyncResult, MemorySegment userData) {
            try (Arena a = Arena.ofConfined()) {
                MemorySegment errorPtr = a.allocate(ValueLayout.ADDRESS);
                MemorySegment sess = invokePointer(H.CREATE_REMOTE_DESKTOP_SESSION_FINISH,
                        portal, asyncResult, errorPtr);
                MemorySegment err = errorPtr.get(ValueLayout.ADDRESS, 0);
                if (err.address() != 0) {
                    error = new RuntimeException("RemoteDesktop session creation failed");
                } else if (sess != null && sess.address() != 0) {
                    session = sess;
                } else {
                    error = new RuntimeException("RemoteDesktop session returned null");
                }
            }
            done = true;
        }
    }


    private static MethodHandle load(String name, FunctionDescriptor fd) {
        MemorySegment sym = LibPortalHolder.LOOKUP.find(name)
                .orElseThrow(() -> new UnsatisfiedLinkError("Missing libportal symbol: " + name));
        return Linker.nativeLinker().downcallHandle(sym, fd);
    }

    public static final int XDP_OPEN_FILE_FLAG_NONE = 0;
    public static final int XDP_OPEN_FILE_FLAG_MULTIPLE = 1;

    private static final int DIALOG_TIMEOUT_MS = 120_000;

    private static final class Gtk4Holder {
        static final SymbolLookup LOOKUP;
        static final boolean AVAILABLE;

        static {
            SymbolLookup gtk4Lib = null;
            boolean gtk4Avail = false;
            if (LibPortalHolder.AVAILABLE) {
                try {
                    gtk4Lib = SymbolLookup.libraryLookup("libportal-gtk4.so.1", Arena.global());
                    gtk4Avail = true;
                } catch (IllegalArgumentException | UnsatisfiedLinkError e1) {
                    try {
                        gtk4Lib = SymbolLookup.libraryLookup("libportal-gtk4.so", Arena.global());
                        gtk4Avail = true;
                    } catch (IllegalArgumentException | UnsatisfiedLinkError ignored) {
                    }
                }
            }
            LOOKUP = gtk4Lib;
            AVAILABLE = gtk4Avail;
        }
    }

    public static MemorySegment parentNewGtk(MemorySegment gtkWindow) {
        if (!Gtk4Holder.AVAILABLE || gtkWindow == null || gtkWindow.address() == 0) {
            return MemorySegment.NULL;
        }
        return invokePointer(H.PARENT_NEW_GTK, gtkWindow);
    }

